// ── NLTK corpora detection ──────────────────────────────────────────────────
const NLTK_CORPORA_SET = new Set([
  "wordnet","stopwords","punkt","punkt_tab",
  "averaged_perceptron_tagger","averaged_perceptron_tagger_eng",
  "maxent_ne_chunker","maxent_ne_chunker_tab",
  "words","omw-1.4","vader_lexicon",
  "twitter_samples","movie_reviews","brown","reuters",
  "gutenberg","inaugural","treebank","conll2000",
  "names","webtext","senseval","abc","genesis",
  "nps_chat","sinica_treebank","cess_cat","cess_esp",
  "floresta","indian","mac_morpho","machado","pl196x",
  "rte","semcor","shakespeare","verbnet",
]);

function detectNltkCorpora(code) {
  const needed = new Set();
  // Explicit nltk.download() calls
  const re = /nltk\.download\s*\(\s*['"]([^'"]+)['"]/g;
  let m;
  while ((m = re.exec(code)) !== null) { if (NLTK_CORPORA_SET.has(m[1])) needed.add(m[1]); }
  // Implicit corpus usage patterns
  if (/nltk\.corpus\.wordnet|from\s+nltk\.corpus\s+import\s+wordnet|\bwn\b/.test(code)) {
    needed.add("wordnet"); needed.add("omw-1.4");
  }
  if (/nltk\.corpus\.stopwords|stopwords\.words|from\s+nltk\.corpus\s+import\s+stopwords/.test(code)) {
    needed.add("stopwords");
  }
  if (/word_tokenize|sent_tokenize|PunktSentenceTokenizer|PunktTokenizer/.test(code)) {
    needed.add("punkt"); needed.add("punkt_tab");
  }
  if (/pos_tag|nltk\.tag|PerceptronTagger/.test(code)) {
    needed.add("averaged_perceptron_tagger"); needed.add("averaged_perceptron_tagger_eng");
  }
  if (/ne_chunk|nltk\.chunk/.test(code)) {
    needed.add("maxent_ne_chunker"); needed.add("maxent_ne_chunker_tab"); needed.add("words");
  }
  if (/SentimentIntensityAnalyzer|vader_lexicon|from\s+nltk\.sentiment/.test(code)) {
    needed.add("vader_lexicon");
  }
  if (/WordNetLemmatizer|lemmatize/.test(code)) { needed.add("wordnet"); needed.add("omw-1.4"); }
  if (/PorterStemmer|LancasterStemmer|SnowballStemmer/.test(code)) { needed.add("punkt"); }
  if (/corpus\.brown/.test(code)) needed.add("brown");
  if (/corpus\.reuters/.test(code)) needed.add("reuters");
  if (/corpus\.movie_reviews/.test(code)) needed.add("movie_reviews");
  if (/corpus\.names/.test(code)) needed.add("names");
  if (/corpus\.gutenberg/.test(code)) needed.add("gutenberg");
  if (/corpus\.inaugural/.test(code)) needed.add("inaugural");
  return [...needed];
}

// ── Session-level caches ────────────────────────────────────────────────────
const _installedPkgs  = new Set();
const _nltkDownloaded = new Set(); // corpora successfully fetched this session

function extractImports(code) {
  const names = new Set();
  const re = /^(?:import|from)\s+([a-zA-Z_][a-zA-Z0-9_]*)/gm;
  let m;
  while ((m = re.exec(code)) !== null) names.add(m[1]);
  return [...names];
}

// ── Build a code prefix that sets up matplotlib Agg backend BEFORE user code ──
// Injecting it as a prefix guarantees it runs before any matplotlib import.
function buildMplPrefix(code) {
  const needsMpl = /matplotlib|seaborn|plt\.|sns\./.test(code);
  if (!needsMpl) return "";
  return [
    "import sys as __lms_sys__",
    "if 'matplotlib' not in __lms_sys__.modules:",
    "    import matplotlib as __lms_mpl__",
    "    __lms_mpl__.use('Agg')",
    "import matplotlib.pyplot as __lms_plt__",
    "__lms_plt__.switch_backend('Agg')",
    "",
  ].join("\n");
}

// ── NLTK corpus CDN map ─────────────────────────────────────────────────────
// Pyodide WASM cannot make network requests from Python (nltk.download fails).
// Instead we fetch zip files via JS fetch() and seed them into the WASM VFS.
// Source: raw GitHub mirror of NLTK's corpus packages (zip format).
const NLTK_CORPUS_URLS = {
  "punkt":      "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/tokenizers/punkt.zip",
  "punkt_tab":  "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/tokenizers/punkt_tab.zip",
  "stopwords":  "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/stopwords.zip",
  "wordnet":    "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/wordnet.zip",
  "omw-1.4":    "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/omw-1.4.zip",
  "averaged_perceptron_tagger":     "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/taggers/averaged_perceptron_tagger.zip",
  "averaged_perceptron_tagger_eng": "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/taggers/averaged_perceptron_tagger_eng.zip",
  "maxent_ne_chunker":     "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/chunkers/maxent_ne_chunker.zip",
  "maxent_ne_chunker_tab": "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/chunkers/maxent_ne_chunker_tab.zip",
  "words":         "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/words.zip",
  "vader_lexicon": "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/sentiment/vader_lexicon.zip",
  "brown":       "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/brown.zip",
  "reuters":     "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/reuters.zip",
  "movie_reviews":"https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/movie_reviews.zip",
  "names":       "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/names.zip",
  "inaugural":   "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/inaugural.zip",
  "gutenberg":   "https://raw.githubusercontent.com/nltk/nltk_data/gh-pages/packages/corpora/gutenberg.zip",
};

// Subdirectory under /nltk_data where each corpus type lives
const NLTK_CORPUS_SUBDIR = {
  "punkt":      "tokenizers",
  "punkt_tab":  "tokenizers",
  "averaged_perceptron_tagger":     "taggers",
  "averaged_perceptron_tagger_eng": "taggers",
  "maxent_ne_chunker":     "chunkers",
  "maxent_ne_chunker_tab": "chunkers",
  "vader_lexicon": "sentiment",
};
function _nltkSubdir(corpus) { return NLTK_CORPUS_SUBDIR[corpus] || "corpora"; }

// ── Fetch a corpus zip via JS and unpack it into the Pyodide VFS ────────────
async function _fetchNltkCorpusViaJS(py, corpus) {
  const url = NLTK_CORPUS_URLS[corpus];
  if (!url) return false;
  const subdir = _nltkSubdir(corpus);
  const destDir = `/nltk_data/${subdir}`;
  try {
    const resp = await fetch(url);
    if (!resp.ok) return false;
    const buf = await resp.arrayBuffer();
    // Write the zip into the Pyodide VFS then unzip with Python's zipfile module
    const zipPath = `/nltk_data/__tmp_${corpus}.zip`;
    py.FS.mkdirTree(destDir);
    py.FS.writeFile(zipPath, new Uint8Array(buf));
    await py.runPythonAsync(
      `import zipfile as __zf\n` +
      `__zf.ZipFile(${JSON.stringify(zipPath)}).extractall(${JSON.stringify(destDir)})\n` +
      `import os as __os; __os.remove(${JSON.stringify(zipPath)})\n`
    );
    return true;
  } catch (_) {
    return false;
  }
}

// ── Build a code prefix that injects NLTK data path + downloads all needed corpora ──
// Returns { prefix: string, log: string }
async function buildNltkPrefix(py, code, imports) {
  const needsNltk = imports.includes("nltk") || _installedPkgs.has("nltk");
  if (!needsNltk) return { prefix: "", log: "" };

  const BASE_PATCH = [
    "import nltk as __lms_nltk__, os as __lms_os__",
    "__lms_os__.makedirs('/nltk_data', exist_ok=True)",
    "if '/nltk_data' not in __lms_nltk__.data.path:",
    "    __lms_nltk__.data.path.insert(0, '/nltk_data')",
    // Patch nltk.download to a no-op — real downloads happen via JS fetch above.
    // This silences user-written nltk.download() calls that cannot work in WASM.
    "__lms_nltk__.download = lambda *a, **kw: True",
    "",
  ].join("\n");

  // Always run the path patch in the engine context first
  try { await py.runPythonAsync(BASE_PATCH); } catch (_) {}

  const needed = detectNltkCorpora(code);
  const toDownload = needed.filter(c => !_nltkDownloaded.has(c));
  let log = "";

  for (const corpus of toDownload) {
    try {
      const ok = await _fetchNltkCorpusViaJS(py, corpus);
      if (ok) {
        _nltkDownloaded.add(corpus);
        log += `✓ nltk data: ${corpus}\n`;
      } else {
        log += `⚠ nltk data ${corpus}: not available via CDN\n`;
      }
    } catch (e) {
      log += `⚠ nltk data ${corpus}: ${e.message.split("\n")[0]}\n`;
    }
  }

  // The prefix injected into user code re-asserts the path every run
  return { prefix: BASE_PATCH, log };
}

// ── Capture ALL matplotlib/seaborn figures as base64 PNGs ──────────────────
async function captureAllFigures(py) {
  const figDataUrls = [];
  try {
    const hasMpl = await py.runPythonAsync(
      `'matplotlib.pyplot' in __import__('sys').modules`
    );
    if (!hasMpl) return figDataUrls;

    const fignums = await py.runPythonAsync(
      `list(__import__('matplotlib').pyplot.get_fignums())`
    );
    const nums = fignums?.toJs ? fignums.toJs() : (Array.isArray(fignums) ? fignums : []);
    if (!nums || nums.length === 0) return figDataUrls;

    for (const num of nums) {
      try {
        const dataUrl = await py.runPythonAsync(`
import io, base64
import matplotlib.pyplot as _cap_plt
_cap_fig = _cap_plt.figure(${num})
_cap_buf = io.BytesIO()
_cap_fig.savefig(_cap_buf, format='png', bbox_inches='tight', dpi=130, facecolor='white')
_cap_buf.seek(0)
'data:image/png;base64,' + base64.b64encode(_cap_buf.read()).decode('utf-8')
`);
        if (dataUrl && dataUrl.startsWith("data:image")) figDataUrls.push(dataUrl);
      } catch (_) {}
    }
    // Close all after capture
    try { await py.runPythonAsync(`import matplotlib.pyplot as _cap_plt; _cap_plt.close('all')`); } catch (_) {}
  } catch (_) {}
  return figDataUrls;
}

// ── Check for WASM-unsupported packages and return a friendly error ─────────
function checkWasmUnsupported(imports) {
  const blocked = imports.filter(n => WASM_UNSUPPORTED[n]);
  if (!blocked.length) return null;
  let msg = "⚠️  Browser (WebAssembly) Limitation\n" + "─".repeat(44) + "\n\n";
  for (const name of blocked) {
    const info = WASM_UNSUPPORTED[name];
    msg += `❌ '${name}' — ${info.reason}\n`;
    msg += `   💡 ${info.alternatives}\n`;
    if (info.colabSnippet) msg += `\n${info.colabSnippet}\n`;
    msg += "\n";
  }
  msg += "─".repeat(44) + "\n";
  msg += "Available alternatives in this browser compiler:\n";
  msg += "  • scikit-learn  — classical ML (SVM, RF, KNN, linear models)\n";
  msg += "  • xgboost       — gradient boosting\n";
  msg += "  • numpy/scipy   — numerical computing\n";
  msg += "  • pandas        — data manipulation\n";
  msg += "  • matplotlib / seaborn — visualisation\n";
  msg += "  • nltk / textblob — NLP without heavy models\n";
  msg += "  • statsmodels   — statistical analysis\n";
  return msg;
}

// ── Main execution engine ───────────────────────────────────────────────────
// Returns { output: string, figureDataUrls: string[] }
async function runPythonReal(code, onStatus, captureMatplotlib = true) {
  const py = await loadPyodide();
  let stdout = "", stderr = "";
  py.setStdout({ batched: t => { stdout += t + "\n"; } });
  py.setStderr({ batched: t => { stderr += t + "\n"; } });
  let pkgLog = "";

  // ── 1. Check for packages that will never work in WASM ─────────
  const imports = extractImports(code);
  const wasmBlock = checkWasmUnsupported(imports);
  if (wasmBlock) return { output: wasmBlock, figureDataUrls: [] };

  // ── 2. Install missing packages ────────────────────────────────
  const missing = imports.filter(n => !_installedPkgs.has(n));
  if (missing.length) {
    try { await py.loadPackage("micropip"); } catch (_) {}
    let micropip;
    try { micropip = py.pyimport("micropip"); } catch (_) {}

    for (const name of missing) {
      // Skip if already importable (e.g. stdlib)
      let ok = false;
      try { ok = await py.runPythonAsync(`__import__('importlib').util.find_spec(${JSON.stringify(name)}) is not None`); } catch (_) {}
      if (ok) { _installedPkgs.add(name); continue; }

      const pkgName = PYODIDE_PKG_MAP[name] || name;
      if (onStatus) onStatus(`📦 Installing ${pkgName}…`);

      let installed = false;
      // Try Pyodide built-in first (fastest)
      if (PYODIDE_BUILTIN_PKGS.has(name) || PYODIDE_BUILTIN_PKGS.has(pkgName)) {
        try {
          await py.loadPackage(pkgName);
          installed = true;
        } catch (_) {}
      }
      // Fall back to micropip
      if (!installed && micropip) {
        try {
          await micropip.install(pkgName);
          installed = true;
        } catch (_) {
          // Last resort: try the raw import name
          try { await micropip.install(name); installed = true; } catch (_) {}
        }
      }
      if (installed) {
        _installedPkgs.add(name);
        pkgLog += `✓ installed ${pkgName}\n`;
      } else {
        pkgLog += `⚠ ${pkgName} — not available in WebAssembly\n`;
      }
    }
  }

  // ── 3. NLTK: download corpora, build path-patch prefix ─────────
  if (onStatus && (imports.includes("nltk") || _installedPkgs.has("nltk"))) {
    const needed = detectNltkCorpora(code).filter(c => !_nltkDownloaded.has(c));
    if (needed.length) onStatus(`📚 Downloading NLTK data: ${needed.join(", ")}…`);
  }
  const { prefix: nltkPrefix, log: nltkLog } = await buildNltkPrefix(py, code, imports);
  pkgLog += nltkLog;

  // ── 4. Matplotlib Agg prefix (injected BEFORE user code) ───────
  const mplPrefix = captureMatplotlib ? buildMplPrefix(code) : "";

  if (onStatus) onStatus(null);

  // ── 5. Run user code (with prefixes prepended) ─────────────────
  const fullCode = mplPrefix + nltkPrefix + code;
  try {
    await py.runPythonAsync(fullCode);

    // ── 6. Capture all matplotlib / seaborn figures ────────────────
    const figureDataUrls = captureMatplotlib ? await captureAllFigures(py) : [];

    const out = (pkgLog ? "Package Log:\n" + pkgLog + "\n" : "")
      + (stdout.trim() || (figureDataUrls.length ? "(plot rendered above)" : "(no output)"))
      + (stderr.trim() ? "\n\nSTDERR:\n" + stderr : "");
    return { output: out, figureDataUrls };

  } catch (e) {
    const rawMsg = e.message || String(e);
    // Strip ANSI escape codes
    const cleanMsg = rawMsg.replace(/\x1b\[[0-9;]*m/g, "");

    // NLTK LookupError — corpus still missing despite our JS-fetch auto-download
    if (cleanMsg.includes("LookupError") && cleanMsg.includes("Resource") && cleanMsg.includes("not found")) {
      const rm = cleanMsg.match(/Resource\s+(\S+)\s+not found/);
      const res = rm ? rm[1].replace(/[^a-z0-9_.-]/gi, "") : "the_corpus";
      // Note: nltk.download() cannot work in browser WASM — don't suggest it.
      const inCdnMap = !!NLTK_CORPUS_URLS[res];
      const hint = [
        pkgLog ? "Package Log:\n" + pkgLog + "\n\n" : "",
        `\u26a0\ufe0f  NLTK Corpus Unavailable: '${res}'\n`,
        "─".repeat(44) + "\n\n",
        inCdnMap
          ? `The corpus '${res}' failed to load from the CDN.\nThis is usually a temporary network issue — try running the code again.\n\n`
          : `The corpus '${res}' is not available in the browser compiler.\nOnly a subset of NLTK corpora can be fetched in a WebAssembly environment.\n\n`,
        `\ud83d\udca1 Available corpora: punkt, punkt_tab, stopwords, wordnet, omw-1.4,\n`,
        `   vader_lexicon, averaged_perceptron_tagger, maxent_ne_chunker, words,\n`,
        `   brown, reuters, movie_reviews, names, inaugural, gutenberg\n\n`,
        `Note: nltk.download() does not work in the browser \u2014 corpora are loaded\n`,
        `automatically via CDN. Remove any nltk.download() calls from your code.\n\n`,
        "Original error:\n" + cleanMsg,
      ].join("");
      return { output: hint, figureDataUrls: [] };
    }

    // ModuleNotFoundError for packages we couldn't install
    if (cleanMsg.includes("ModuleNotFoundError") || cleanMsg.includes("No module named")) {
      const mm = cleanMsg.match(/No module named '([^']+)'/);
      const modName = mm ? mm[1] : "the package";
      const isUnsupported = WASM_UNSUPPORTED[modName.split(".")[0]];
      if (isUnsupported) {
        return { output: checkWasmUnsupported([modName.split(".")[0]]), figureDataUrls: [] };
      }
      const hint = (pkgLog ? "Package Log:\n" + pkgLog + "\n\n" : "")
        + `Module '${modName}' could not be installed.\n`
        + "This may be a package that requires native OS extensions (C/C++ compiled code)\n"
        + "which are not available in the browser WebAssembly environment.\n\n"
        + "Original error:\n" + cleanMsg;
      return { output: hint, figureDataUrls: [] };
    }

    return {
      output: (pkgLog ? "Package Log:\n" + pkgLog + "\n\n" : "") + "Error:\n" + cleanMsg,
      figureDataUrls: [],
    };
  }
}

/* ═══════════════════════════════════════════════════════════════════
   EMBEDDED PYTHON COMPILER — CodeEditor + OutputPane + EmbeddedCompiler
   Replaces the basic textarea with a full-featured IDE panel
═══════════════════════════════════════════════════════════════════ */

// Syntax colour constants (no external dep)
const _KW_RE  = /\b(import|from|as|def|class|return|if|elif|else|for|while|in|not|and|or|is|None|True|False|try|except|finally|raise|with|yield|lambda|pass|break|continue|del|global|nonlocal|assert|async|await)\b/g;
const _STR_RE = /("""[\s\S]*?"""|'''[\s\S]*?'''|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g;
const _CMT_RE = /(#.*)/g;
const _NUM_RE = /\b(\d+\.?\d*)\b/g;
const _FN_RE  = /\b([a-zA-Z_]\w*)\s*(?=\()/g;
const _DEC_RE = /(@\w+)/g;

function pyHighlight(code) {
  let h = code.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
  h = h.replace(_STR_RE,'<span style="color:#98c379">$1</span>');
  h = h.replace(_CMT_RE,'<span style="color:#7f848e;font-style:italic">$1</span>');
  h = h.replace(_DEC_RE,'<span style="color:#e5c07b">$1</span>');
  h = h.replace(_KW_RE, '<span style="color:#c678dd;font-weight:600">$1</span>');
  h = h.replace(_NUM_RE,'<span style="color:#d19a66">$1</span>');
  h = h.replace(_FN_RE, '<span style="color:#61afef">$&</span>');
  return h;
}

// Code editor with line numbers + Tab key support
function PyCodeEditor({ value, onChange, height = 380 }) {
  const taRef = useRef(null);
  const lnRef = useRef(null);
  const onScroll = () => { if (lnRef.current && taRef.current) lnRef.current.scrollTop = taRef.current.scrollTop; };
  const lines = value.split("\n").length;
  const lineNums = Array.from({ length: Math.max(lines, 1) }, (_, i) => i + 1);
  const onKey = (e) => {
    if (e.key === "Tab") {
      e.preventDefault();
      const ta = e.target, start = ta.selectionStart, end = ta.selectionEnd;
      const newVal = value.substring(0, start) + "    " + value.substring(end);
      onChange(newVal);
      setTimeout(() => { ta.selectionStart = ta.selectionEnd = start + 4; }, 0);
    }
  };
  return (
    <div style={{ display:"flex", height, border:"1.5px solid #e2e8f0", borderRadius:10,
      overflow:"hidden", background:"#0d1117", fontFamily:"'JetBrains Mono','Fira Code','Consolas',monospace" }}>
      <div ref={lnRef} style={{ width:44, background:"#161b22", borderRight:"1px solid #30363d",
        overflowY:"hidden", padding:"12px 0", userSelect:"none", scrollbarWidth:"none" }}>
        {lineNums.map(n => (
          <div key={n} style={{ fontSize:11.5, lineHeight:"1.65em", color:"#484f58",
            textAlign:"right", paddingRight:8, paddingLeft:4 }}>{n}</div>
        ))}
      </div>
      <textarea
        ref={taRef} value={value} onChange={e=>onChange(e.target.value)}
        onScroll={onScroll} onKeyDown={onKey}
        spellCheck={false} autoCapitalize="off" autoCorrect="off"
        style={{ flex:1, resize:"none", border:"none", outline:"none", padding:"12px 14px",
          fontSize:12.5, lineHeight:"1.65em", background:"#0d1117", color:"#e6edf3",
          fontFamily:"inherit", overflowY:"auto" }}
      />
    </div>
  );
}

// Output pane — shows text + optional matplotlib/seaborn PNG(s)
function PyOutputPane({ output, figureDataUrls, figureDataUrl, statusMsg, running }) {
  // Accept both old single-url and new array forms for backward-compat
  const figs = Array.isArray(figureDataUrls)
    ? figureDataUrls.filter(Boolean)
    : (figureDataUrl ? [figureDataUrl] : []);

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
      {statusMsg && (
        <div style={{ padding:"7px 12px", background:"#1f3a5f", border:"1px solid #1f6feb",
          borderRadius:8, fontSize:12.5, color:"#79c0ff", display:"flex", alignItems:"center", gap:8 }}>
          <span style={{ display:"inline-block", width:7, height:7, borderRadius:"50%",
            background:"#1f6feb", animation:"lms-spin 1s linear infinite" }} />
          {statusMsg}
        </div>
      )}
      {figs.map((url, idx) => (
        <div key={idx} style={{ background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", border:"1px solid #fff", borderRadius:14, overflow:"hidden", boxShadow:"8px 8px 20px #C4CDD9,-5px -5px 14px #fff" }}>
          <div style={{ padding:"6px 12px", fontSize:11.5, fontWeight:600, color:"#64748b",
            borderBottom:"1px solid #C4CDD9", background:"linear-gradient(145deg,#E4E9F2,#EDF1F7)", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
            <span>📊 {figs.length > 1 ? `Figure ${idx + 1} of ${figs.length}` : "Plot Output"}</span>
            <a href={url} download={`figure_${idx + 1}.png`} onClick={e => { if (!canDownload()) e.preventDefault(); }}
              style={{ fontSize:10.5, color:"#3b82f6", textDecoration:"none", fontWeight:500 }}>⬇ Save PNG</a>
          </div>
          <img src={url} alt={`Figure ${idx + 1}`} style={{ maxWidth:"100%", display:"block" }} />
        </div>
      ))}
      <div className="lms-output" style={{ minHeight:240, maxHeight:360, overflowY:"auto",
        fontFamily:"'JetBrains Mono','Fira Code',monospace", fontSize:12, lineHeight:1.7,
        whiteSpace:"pre-wrap", wordBreak:"break-word" }}>
        {running && !output
          ? <span style={{ color:"#94a3b8" }}>⟳ Running…</span>
          : output || <span style={{ color:"#94a3b8" }}>▶ Run your code to see output here</span>}
      </div>
    </div>
  );
}

// Snippet presets available in the compiler sidebar
const COMPILER_SNIPPETS = [
  { label:"Hello World",    code:`print("Hello, World!")\nimport sys\nprint(f"Python {sys.version.split()[0]}")` },
  { label:"NumPy basics",   code:`import numpy as np\na = np.array([1,2,3,4,5])\nprint("mean:", np.mean(a))\nprint("std:", np.std(a))` },
  { label:"Pandas DataFrame", code:`import pandas as pd\ndf = pd.DataFrame({"a":[1,2,3],"b":[4,5,6]})\nprint(df)\nprint(df.describe())` },
  { label:"Matplotlib plot", code:`import matplotlib.pyplot as plt\nimport numpy as np\nx = np.linspace(0, 10, 200)\nplt.figure(figsize=(7,3))\nplt.plot(x, np.sin(x), label='sin')\nplt.plot(x, np.cos(x), label='cos')\nplt.title("Trig Functions")\nplt.legend()\nplt.tight_layout()\nplt.show()\nprint("Plot rendered above ↑")` },
  { label:"Seaborn heatmap", code:`import seaborn as sns\nimport matplotlib.pyplot as plt\nimport numpy as np\ndata = np.random.rand(8, 8)\nplt.figure(figsize=(6,5))\nsns.heatmap(data, annot=True, fmt=".2f", cmap="Blues")\nplt.title("Seaborn Heatmap")\nplt.tight_layout()\nplt.show()\nprint("Heatmap rendered above ↑")` },
  { label:"Multi-plot",     code:`import matplotlib.pyplot as plt\nimport numpy as np\nx = np.linspace(0, 10, 100)\nfig, axes = plt.subplots(1, 2, figsize=(10, 3))\naxes[0].plot(x, np.sin(x), color='steelblue')\naxes[0].set_title('Sine')\naxes[1].plot(x, x**2, color='coral')\naxes[1].set_title('Parabola')\nplt.tight_layout()\nplt.show()\nprint("Two plots rendered above ↑")` },
  { label:"Sklearn RF",     code:`from sklearn.datasets import make_classification\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import accuracy_score\nX, y = make_classification(n_samples=200, random_state=42)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.2)\nclf = RandomForestClassifier().fit(X_tr, y_tr)\nprint("Accuracy:", accuracy_score(y_te, clf.predict(X_te)))` },
  { label:"NLTK stopwords", code:`import nltk\nfrom nltk.corpus import stopwords\nfrom nltk.tokenize import word_tokenize\n\ntext = "Natural language processing is a fascinating area of artificial intelligence"\ntokens = word_tokenize(text.lower())\nstop_words = set(stopwords.words('english'))\nfiltered = [w for w in tokens if w.isalpha() and w not in stop_words]\nprint("Original:", tokens)\nprint("Filtered:", filtered)` },
  { label:"NLTK lemmatizer", code:`import nltk\nfrom nltk.stem import WordNetLemmatizer\nfrom nltk.corpus import wordnet\n\nlemmatizer = WordNetLemmatizer()\nwords = ["running", "flies", "better", "studies", "geese", "cached"]\nfor w in words:\n    print(f"{w:15} → {lemmatizer.lemmatize(w, pos=wordnet.VERB)}")` },
  { label:"NLTK sentiment",  code:`import nltk\nfrom nltk.sentiment import SentimentIntensityAnalyzer\n\nsia = SentimentIntensityAnalyzer()\nsentences = [\n    "I absolutely love this! It's amazing.",\n    "This is okay, nothing special.",\n    "Terrible experience. I'm very disappointed.",\n]\nfor s in sentences:\n    scores = sia.polarity_scores(s)\n    label = "positive" if scores["compound"] > 0.05 else "negative" if scores["compound"] < -0.05 else "neutral"\n    print(f"[{label:8}] {s[:45]}")` },
  { label:"TensorFlow note", code:`# TensorFlow / PyTorch / Keras cannot run in this\n# browser compiler because they require native C/CUDA\n# extensions not available in WebAssembly.\n#\n# ✅  Use these instead for ML in the browser:\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.datasets import make_moons\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import accuracy_score\n\nX, y = make_moons(n_samples=300, noise=0.2, random_state=42)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.2)\nmlp = MLPClassifier(hidden_layer_sizes=(64, 32), max_iter=500, random_state=42)\nmlp.fit(X_tr, y_tr)\nprint(f"MLP Neural Net accuracy: {accuracy_score(y_te, mlp.predict(X_te)):.3f}")` },
  { label:"XGBoost",         code:`import xgboost as xgb\nfrom sklearn.datasets import load_breast_cancer\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.metrics import accuracy_score\n\ndata = load_breast_cancer()\nX_tr, X_te, y_tr, y_te = train_test_split(data.data, data.target, test_size=0.2, random_state=42)\nmodel = xgb.XGBClassifier(n_estimators=100, eval_metric='logloss')\nmodel.fit(X_tr, y_tr)\nprint("XGBoost accuracy:", accuracy_score(y_te, model.predict(X_te)))` },
  { label:"scipy",          code:`import scipy\nprint(scipy.__version__)` },
  { label:"nltk version",   code:`import nltk\nprint(nltk.__version__)` },
];

// Full embedded compiler component used inside DayPage compiler tab
function EmbeddedCompiler({ initialCode = "", dayTopic = "", pyodideReady, pyodideLoading, onLoadPyodide, onCodeChange, trackActivity, dayKey }) {
  const [tabs, setTabs] = useState([{ id:"main", name:"main.py", code: initialCode }]);
  const [activeTab, setActiveTab]     = useState("main");
  const [editingTabId, setEditingTabId] = useState(null);
  const [tabNameDraft, setTabNameDraft] = useState("");

  const activeCode = tabs.find(t => t.id === activeTab)?.code ?? "";
  const setActiveCode = useCallback((code) => {
    setTabs(prev => prev.map(t => t.id === activeTab ? { ...t, code } : t));
    if (onCodeChange) onCodeChange(code);
  }, [activeTab, onCodeChange]);

  // Sync initialCode into main tab when it changes from outside (e.g. "Use Code" in notebook)
  useEffect(() => {
    if (initialCode && initialCode !== tabs.find(t => t.id === "main")?.code) {
      setTabs(prev => prev.map(t => t.id === "main" ? { ...t, code: initialCode } : t));
      setActiveTab("main");
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialCode]);

  const [running, setRunning]         = useState(false);
  const [output, setOutput]           = useState("");
  const [statusMsg, setStatusMsg]     = useState(null);
  const [figureDataUrls, setFigureDataUrls] = useState([]);
  const [runCount, setRunCount]       = useState(0);
  const [lastRunMs, setLastRunMs]     = useState(null);

  const handleRun = useCallback(async () => {
    if (running || !pyodideReady) return;
    setRunning(true); setOutput(""); setFigureDataUrls([]); setStatusMsg("⟳ Starting…");
    const t0 = performance.now();
    try {
      const { output: out, figureDataUrls: figs } = await runPythonReal(activeCode, setStatusMsg);
      setOutput(out); setFigureDataUrls(figs || []);
      setRunCount(c => c + 1); setLastRunMs(Math.round(performance.now() - t0));
      if (trackActivity && dayKey) trackActivity("codeRun", dayKey, true);
    } catch (e) { setOutput("Fatal error: " + e.message); }
    setStatusMsg(null); setRunning(false);
  }, [running, pyodideReady, activeCode, trackActivity, dayKey]);

  // Ctrl/Cmd+Enter shortcut
  useEffect(() => {
    const h = (e) => { if ((e.ctrlKey || e.metaKey) && e.key === "Enter") { e.preventDefault(); handleRun(); } };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [handleRun]);

  const addTab = () => {
    const id = "tab_" + Date.now(), n = tabs.length + 1;
    setTabs(prev => [...prev, { id, name:`script_${n}.py`, code:`# script_${n}.py\nprint("Hello from script ${n}")\n` }]);
    setActiveTab(id);
  };
  const closeTab = (id) => {
    if (tabs.length === 1) return;
    const idx = tabs.findIndex(t => t.id === id);
    const newTabs = tabs.filter(t => t.id !== id);
    setTabs(newTabs);
    if (activeTab === id) setActiveTab(newTabs[Math.max(0, idx - 1)].id);
  };

  const downloadPy = () => {
    const tab = tabs.find(t => t.id === activeTab);
    downloadBlob(tab.code, tab.name, "text/x-python");
  };
  const downloadOutput = () => { if (output) downloadBlob(output, "output.txt"); };

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:0 }}>
      {/* ── Pyodide status banner ── */}
      {!pyodideReady ? (
        <div style={{ background:"#eff6ff", border:"1.5px solid #bfdbfe", borderRadius:10, padding:"10px 16px", marginBottom:14, display:"flex", alignItems:"center", justifyContent:"space-between", gap:12, flexWrap:"wrap" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8, fontSize:13, color:"#1e40af" }}>
            <Ic n="zap" s={15} c="#3b82f6"/>
            <div>
              <strong>Real Python Execution available</strong> — load Pyodide (WASM) for actual code running
              <div style={{ fontSize:11.5, color:"#3b82f6", marginTop:2 }}>
                📦 pandas, numpy, scikit-learn, matplotlib &amp; 100+ packages auto-install on first use
              </div>
            </div>
          </div>
          <button className="lms-btn lms-btn-blue" disabled={pyodideLoading} onClick={onLoadPyodide} style={{ flexShrink:0 }}>
            {pyodideLoading?<><Spin s={13}/>Loading Python...</>:<><Ic n="play" s={13}/>Load Real Python</>}
          </button>
        </div>
      ) : (
        <div style={{ background:"#f0fdf4", border:"1.5px solid #bbf7d0", borderRadius:10, padding:"8px 16px", marginBottom:14, fontSize:13, color:"#15803d", fontWeight:600, display:"flex", alignItems:"center", justifyContent:"space-between", gap:8 }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <Ic n="check" s={15} c="#22c55e"/>
            Real Python · Pyodide WASM · auto-install ON
            {lastRunMs && <span style={{ fontSize:11, fontWeight:400, color:"#16a34a" }}>· last run {lastRunMs}ms · {runCount} total</span>}
          </div>
          <span style={{ fontSize:11, fontWeight:400, color:"#16a34a" }}>Ctrl+Enter to run</span>
        </div>
      )}

      <div style={{ display:"grid", gridTemplateColumns:"160px 1fr", gap:14, alignItems:"start" }}>
        {/* ── Snippets sidebar ── */}
        <div className="lms-card" style={{ padding:12 }}>
          <p style={{ fontSize:11, fontWeight:700, color:"#94a3b8", textTransform:"uppercase", letterSpacing:".08em", marginBottom:8 }}>Snippets</p>
          <div style={{ display:"flex", flexDirection:"column", gap:2 }}>
            {COMPILER_SNIPPETS.map((s, i) => (
              <button key={i} onClick={() => { setActiveCode(s.code); setOutput(""); setFigureDataUrls([]); }}
                style={{ width:"100%", textAlign:"left", background:"transparent", border:"none",
                  padding:"5px 8px", fontSize:12, color:"#475569", cursor:"pointer", borderRadius:6,
                  display:"flex", alignItems:"center", gap:6, transition:"background .1s" }}
                onMouseEnter={e=>e.currentTarget.style.background="#f1f5f9"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <span style={{ width:6, height:6, borderRadius:"50%", background:"#3b82f6", flexShrink:0 }} />
                {s.label}
              </button>
            ))}
          </div>
          <div style={{ height:1, background:"#e2e8f0", margin:"10px 0" }} />
          <p style={{ fontSize:10, color:"#94a3b8", lineHeight:1.5 }}>Tab → 4 spaces<br/>Ctrl+↵ → Run</p>
          <div style={{ height:1, background:"#e2e8f0", margin:"10px 0" }} />
          <div style={{ background:"#f0fdf4", border:"1px solid #bbf7d0", borderRadius:6, padding:8 }}>
            <p style={{ fontSize:10.5, fontWeight:700, color:"#16a34a", margin:"0 0 3px" }}>📦 Auto-Install ON</p>
            <p style={{ fontSize:10, color:"#64748b", margin:0, lineHeight:1.4 }}>Any import auto-installs. NLTK corpora auto-download. Plots render as images.</p>
          </div>
          <div style={{ height:1, background:"#e2e8f0", margin:"8px 0" }} />
          <div style={{ background:"#fff7ed", border:"1px solid #fed7aa", borderRadius:6, padding:8 }}>
            <p style={{ fontSize:10.5, fontWeight:700, color:"#c2410c", margin:"0 0 3px" }}>⚠️ WASM Limits</p>
            <p style={{ fontSize:10, color:"#64748b", margin:0, lineHeight:1.4 }}>TensorFlow, PyTorch &amp; Keras need native GPU drivers — use scikit-learn or run locally.</p>
          </div>
        </div>

        {/* ── Editor + Output ── */}
        <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
          {/* File tabs */}
          <div style={{ display:"flex", alignItems:"center", gap:2, borderBottom:"1.5px solid #e2e8f0", paddingBottom:0 }}>
            {tabs.map(tab => (
              <div key={tab.id}
                style={{ display:"flex", alignItems:"center", gap:4, padding:"6px 12px 5px",
                  background: tab.id===activeTab ? "#fff" : "transparent",
                  borderBottom: tab.id===activeTab ? "2px solid #3b82f6" : "2px solid transparent",
                  cursor:"pointer", borderRadius:"6px 6px 0 0" }}
                onClick={() => setActiveTab(tab.id)}>
                {editingTabId === tab.id ? (
                  <input autoFocus value={tabNameDraft}
                    onChange={e=>setTabNameDraft(e.target.value)}
                    onBlur={()=>{ if(tabNameDraft.trim()) setTabs(p=>p.map(t=>t.id===tab.id?{...t,name:tabNameDraft.trim()}:t)); setEditingTabId(null); }}
                    onKeyDown={e=>{ if(e.key==="Enter") e.target.blur(); if(e.key==="Escape") setEditingTabId(null); }}
                    style={{ fontSize:12, border:"none", background:"transparent", color:"#0f172a",
                      outline:"1px solid #3b82f6", borderRadius:3, width:90, fontFamily:"inherit" }} />
                ) : (
                  <span style={{ fontSize:12, color: tab.id===activeTab?"#0f172a":"#64748b" }}
                    onDoubleClick={()=>{ setTabNameDraft(tab.name); setEditingTabId(tab.id); }}>
                    📄 {tab.name}
                  </span>
                )}
                {tabs.length > 1 && (
                  <span onClick={e=>{ e.stopPropagation(); closeTab(tab.id); }}
                    style={{ fontSize:13, color:"#94a3b8", lineHeight:1, cursor:"pointer", padding:"0 2px", borderRadius:3 }}>×</span>
                )}
              </div>
            ))}
            <button onClick={addTab}
              style={{ padding:"4px 10px", background:"transparent", border:"none",
                color:"#94a3b8", cursor:"pointer", fontSize:16, lineHeight:1, marginLeft:2 }}>+</button>
            <div style={{ flex:1 }} />
            <span style={{ fontSize:11, color:"#94a3b8", paddingBottom:6 }}>
              {activeCode.split("\n").length} lines · {activeCode.length} chars
            </span>
          </div>

          {/* Editor + Output grid */}
          <div className="lms-compiler-grid" style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14 }}>
            {/* Editor */}
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              <p style={{ fontWeight:700, fontSize:12.5, color:"#0f172a", margin:0 }}>
                Editor{dayTopic ? ` — ${dayTopic}` : ""}
              </p>
              <PyCodeEditor value={activeCode} onChange={setActiveCode} height={360} />
            </div>
            {/* Output */}
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              <p style={{ fontWeight:700, fontSize:12.5, color:"#0f172a", margin:0 }}>
                Output <span style={{ fontSize:11, color:"#94a3b8", fontWeight:400 }}>
                  ({pyodideReady ? "Real Pyodide WASM" : "load Python above to run"})
                </span>
              </p>
              <PyOutputPane output={output} figureDataUrls={figureDataUrls} statusMsg={statusMsg} running={running} />
            </div>
          </div>

          {/* Action bar */}
          <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
            <button className="lms-btn lms-btn-blue" disabled={running || !pyodideReady} onClick={handleRun}
              style={{ padding:"8px 20px" }}>
              {running ? <><Spin s={13}/>Running…</> : <><Ic n="play" s={13}/>Run Code</>}
            </button>
            <button className="lms-btn lms-btn-ghost" onClick={() => { setOutput(""); setFigureDataUrls([]); }}>
              <Ic n="x" s={12}/>Clear Output
            </button>
            <button className="lms-btn lms-btn-ghost" onClick={downloadPy}>
              <Ic n="download" s={12}/>Download .py
            </button>
            {output && (
              <button className="lms-btn lms-btn-ghost" onClick={downloadOutput}>
                <Ic n="download" s={12}/>Download Output
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   FIX 9: OFFLINE INDICATOR HOOK
═══════════════════════════════════════════════════════════════════ */
function useOnlineStatus() {
  const [online, setOnline] = useState(navigator.onLine);
  useEffect(() => {
    const on = () => setOnline(true);
    const off = () => setOnline(false);
    window.addEventListener("online", on);
    window.addEventListener("offline", off);
    return () => { window.removeEventListener("online", on); window.removeEventListener("offline", off); };
  }, []);
  return online;
}

/* ═══════════════════════════════════════════════════════════════════
   FIX 3 + FIX 15: ERROR BOUNDARY
   The key-based remount trick only works when the key is on the
   ErrorBoundary itself (from its parent). We expose a resetKey prop
   and use a thin wrapper component (ResettableErrorBoundary) that
   increments it, forcing a full unmount+remount of the boundary and
   its children — preventing an immediate re-crash on "Try Again".
═══════════════════════════════════════════════════════════════════ */
class ErrorBoundaryInner extends Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error, info) { console.error("LMS crashed:", error, info); }
  render() {
    if (this.state.error) {
      return (
        <div style={{ padding: 40, textAlign: "center", fontFamily: "system-ui" }}>
          <div style={{ fontSize: 48, marginBottom: 16 }}>⚠️</div>
          <h2 style={{ color: "#dc2626", marginBottom: 12 }}>Something went wrong</h2>
          <p style={{ color: "#64748b", marginBottom: 20, maxWidth: 400, margin: "0 auto 20px" }}>
            {this.state.error.message}
          </p>
          <button
            style={{ padding: "10px 24px", background: "#0f172a", color: "#fff", border: "none", borderRadius: 9, cursor: "pointer", fontSize: 14, fontWeight: 600 }}
            onClick={() => this.props.onReset()}
          >
            Try Again
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

// FIX 15: Wrapper that holds resetKey in state; incrementing it remounts
// ErrorBoundaryInner (and therefore all its children) from scratch.
function ErrorBoundary({ children }) {
  const [resetKey, setResetKey] = useState(0);
  return (
    <ErrorBoundaryInner key={resetKey} onReset={() => setResetKey(k => k + 1)}>
      {children}
    </ErrorBoundaryInner>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   ICONS
═══════════════════════════════════════════════════════════════════ */
const Ic = ({ n, s=16, c="currentColor" }) => {
  const a = { width:s, height:s, viewBox:"0 0 24 24", fill:"none", stroke:c, strokeWidth:"2", strokeLinecap:"round", strokeLinejoin:"round" };
  if (n==="home")     return <svg {...a}><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>;
  if (n==="book")     return <svg {...a}><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>;
  if (n==="calendar") return <svg {...a}><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>;
  if (n==="settings") return <svg {...a}><circle cx="12" cy="12" r="3"/><path d="M19.07 4.93l-1.41 1.41M4.93 4.93l1.41 1.41M4.93 19.07l1.41-1.41M19.07 19.07l-1.41-1.41M12 2v2M12 20v2M2 12h2M20 12h2"/></svg>;
  if (n==="upload")   return <svg {...a}><polyline points="16 16 12 12 8 16"/><line x1="12" y1="12" x2="12" y2="21"/><path d="M20.39 18.39A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.3"/></svg>;
  if (n==="download") return <svg {...a}><polyline points="8 17 12 21 16 17"/><line x1="12" y1="12" x2="12" y2="21"/><path d="M20.88 18.09A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.3"/></svg>;
  if (n==="play")     return <svg {...a}><polygon points="5 3 19 12 5 21 5 3"/></svg>;
  if (n==="check")    return <svg {...a}><polyline points="20 6 9 17 4 12"/></svg>;
  if (n==="x")        return <svg {...a}><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>;
  if (n==="plus")     return <svg {...a}><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>;
  if (n==="brain")    return <svg {...a}><path d="M9.5 2A2.5 2.5 0 0 1 12 4.5v15a2.5 2.5 0 0 1-4.96-.46 2.5 2.5 0 0 1-1.98-3A3 3 0 0 1 4 12a3 3 0 0 1 1.06-2.29 2.5 2.5 0 0 1 1.98-3A2.5 2.5 0 0 1 9.5 2Z"/><path d="M14.5 2A2.5 2.5 0 0 0 12 4.5v15a2.5 2.5 0 0 0 4.96-.46 2.5 2.5 0 0 0 1.98-3A3 3 0 0 0 20 12a3 3 0 0 0-1.06-2.29 2.5 2.5 0 0 0-1.98-3A2.5 2.5 0 0 0 14.5 2Z"/></svg>;
  if (n==="code")     return <svg {...a}><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg>;
  if (n==="file")     return <svg {...a}><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>;
  if (n==="chevL")    return <svg {...a}><polyline points="15 18 9 12 15 6"/></svg>;
  if (n==="chevR")    return <svg {...a}><polyline points="9 18 15 12 9 6"/></svg>;
  if (n==="menu")     return <svg {...a}><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="18" x2="21" y2="18"/></svg>;
  if (n==="clip")     return <svg {...a}><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><rect x="8" y="2" width="8" height="4" rx="1" ry="1"/></svg>;
  if (n==="loader")   return <svg {...a}><line x1="12" y1="2" x2="12" y2="6"/><line x1="12" y1="18" x2="12" y2="22"/><line x1="4.93" y1="4.93" x2="7.76" y2="7.76"/><line x1="16.24" y1="16.24" x2="19.07" y2="19.07"/><line x1="2" y1="12" x2="6" y2="12"/><line x1="18" y1="12" x2="22" y2="12"/><line x1="4.93" y1="19.07" x2="7.76" y2="16.24"/><line x1="16.24" y1="7.76" x2="19.07" y2="4.93"/></svg>;
  if (n==="zap")      return <svg {...a}><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>;
  if (n==="teacher")  return <svg {...a}><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>;
  if (n==="chart")    return <svg {...a}><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>;
  if (n==="trash")    return <svg {...a}><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/></svg>;
  if (n==="img")      return <svg {...a}><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>;
  if (n==="pdf")      return <svg {...a}><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>;
  if (n==="db")       return <svg {...a}><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg>;
  if (n==="bell")     return <svg {...a}><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>;
  if (n==="lock")     return <svg {...a}><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>;
  if (n==="user")     return <svg {...a}><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>;
  if (n==="wifi-off") return <svg {...a}><line x1="1" y1="1" x2="23" y2="23"/><path d="M16.72 11.06A10.94 10.94 0 0 1 19 12.55"/><path d="M5 12.55a10.94 10.94 0 0 1 5.17-2.39"/><path d="M10.71 5.05A16 16 0 0 1 22.56 9"/><path d="M1.42 9a15.91 15.91 0 0 1 4.7-2.88"/><path d="M8.53 16.11a6 6 0 0 1 6.95 0"/><line x1="12" y1="20" x2="12.01" y2="20"/></svg>;
  if (n==="refresh")  return <svg {...a}><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>;
  if (n==="search")   return <svg {...a}><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>;
  if (n==="shield")   return <svg {...a}><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>;
  if (n==="clipbrd")  return <svg {...a}><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><rect x="8" y="2" width="8" height="4" rx="1" ry="1"/><line x1="8" y1="11" x2="16" y2="11"/><line x1="8" y1="15" x2="12" y2="15"/></svg>;
  return null;
};

const Spin = ({ s=14 }) => (
  <span style={{ display:"inline-flex", animation:"lms-spin 0.8s linear infinite" }}>
    <Ic n="loader" s={s} />
  </span>
);


/* ═══════════════════════════════════════════════════════════════════
   LOGIN SCREEN — uses Supabase for all auth
═══════════════════════════════════════════════════════════════════ */
/* ═══════════════════════════════════════════════════════════════════
   COURSE CATALOGUE — step 2 of student sign-up
   A checkbox list stops working once a trainer has more than a handful of
   courses. This is a searchable grid instead: every course gets a monogram
   tile whose colour is derived from its own name, so a long catalogue stays
   scannable, and the running selection sits in a tray that follows you down
   the page.
═══════════════════════════════════════════════════════════════════ */
function courseAccent(name) {
  // Deterministic hue per course — the same course always looks the same.
  let h = 0;
  const s = String(name || "?");
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;
  return {
    from: `hsl(${h} 72% 58%)`,
    to:   `hsl(${(h + 38) % 360} 74% 46%)`,
    soft: `hsl(${h} 80% 96%)`,
    edge: `hsl(${h} 60% 82%)`,
    ink:  `hsl(${h} 62% 32%)`,
  };
}

function courseMonogram(name) {
  const words = String(name || "?").trim().split(/\s+/).filter(Boolean);
  if (!words.length) return "?";
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
  return (words[0][0] + words[1][0]).toUpperCase();
}

export function CourseSelectPage({ courses, trainersMap, selectedIds, setSelectedIds, onBack, onSubmit, loading, error, studentName }) {
  const [query, setQuery] = useState("");
  const [trainerFilter, setTrainerFilter] = useState("all");
  const [hovered, setHovered] = useState(null);

  const trainerNames = useMemo(() => {
    const m = new Map();
    courses.forEach(c => {
      const t = trainersMap[c.trainerId];
      if (t) m.set(c.trainerId, t.name);
    });
    return Array.from(m.entries());
  }, [courses, trainersMap]);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return courses.filter(c => {
      if (trainerFilter !== "all" && c.trainerId !== trainerFilter) return false;
      if (!q) return true;
      const tName = trainersMap[c.trainerId]?.name || "";
      return c.name.toLowerCase().includes(q) || tName.toLowerCase().includes(q);
    });
  }, [courses, query, trainerFilter, trainersMap]);

  const toggle = (id) => setSelectedIds(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  const selectedCourses = courses.filter(c => selectedIds.includes(c.id));
  const totalDays = selectedCourses.reduce((s, c) => s + (Array.isArray(c.planDays) ? c.planDays.length : 0), 0);

  return (
    <div className="csp">
      <style>{`
        .csp{min-height:100vh;position:relative;overflow-x:hidden;padding-bottom:150px;
          font-family:'Segoe UI','Helvetica Neue',system-ui,sans-serif;
          background:#0d0a1a;}
        /* Slow-drifting colour wash behind everything */
        .csp::before{content:"";position:fixed;inset:-30%;z-index:0;pointer-events:none;
          background:
            radial-gradient(620px 620px at 18% 12%,rgba(124,58,237,.34),transparent 62%),
            radial-gradient(560px 560px at 82% 26%,rgba(56,189,248,.2),transparent 60%),
            radial-gradient(680px 680px at 50% 92%,rgba(236,72,153,.17),transparent 62%);
          animation:csp-drift 22s ease-in-out infinite alternate;}
        @keyframes csp-drift{
          0%{transform:translate3d(0,0,0) scale(1);}
          100%{transform:translate3d(-3%,-2%,0) scale(1.1);}
        }
        .csp::after{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;opacity:.35;
          background-image:radial-gradient(rgba(255,255,255,.07) 1px,transparent 1px);
          background-size:26px 26px;}
        .csp-in{position:relative;z-index:1;max-width:1120px;margin:0 auto;padding:0 28px;}

        .csp-back{background:none;border:none;color:#a78bfa;font-weight:600;font-size:13.5px;cursor:pointer;padding:0;margin-bottom:22px;transition:color .16s;}
        .csp-back:hover{color:#ddd4ff;}
        .csp-step{display:inline-flex;align-items:center;gap:9px;padding:6px 14px;border-radius:99px;
          background:rgba(167,139,250,.14);border:1px solid rgba(167,139,250,.3);margin-bottom:16px;}
        .csp-dot{width:6px;height:6px;border-radius:99px;background:#a78bfa;box-shadow:0 0 10px #a78bfa;}
        .csp-steptext{font-size:11.5px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;color:#c4b5fd;}
        .csp-h1{font-size:clamp(30px,5vw,50px);font-weight:800;color:#fff;letter-spacing:-1.2px;line-height:1.08;margin-bottom:13px;}
        .csp-h1 em{font-style:normal;background:linear-gradient(105deg,#c4b5fd,#7dd3fc 45%,#f0abfc);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;}
        .csp-lead{font-size:15.5px;color:#a79fc4;max-width:620px;line-height:1.68;}

        .csp-controls{display:flex;gap:11px;flex-wrap:wrap;align-items:center;margin:30px 0 22px;}
        .csp-searchwrap{position:relative;flex:1 1 280px;}
        .csp-searchicon{position:absolute;left:17px;top:50%;transform:translateY(-50%);color:#7c6aa8;font-size:15px;pointer-events:none;}
        .csp-search{width:100%;padding:14px 18px 14px 42px;border-radius:14px;font-size:14.5px;box-sizing:border-box;
          background:rgba(255,255,255,.05);border:1.5px solid rgba(255,255,255,.11);color:#eee;outline:none;
          backdrop-filter:blur(10px);transition:border-color .18s,background .18s;}
        .csp-search::placeholder{color:#6f6592;}
        .csp-search:focus{border-color:#8b5cf6;background:rgba(255,255,255,.08);box-shadow:0 0 0 4px rgba(139,92,246,.16);}
        .csp-pill{padding:10px 16px;border-radius:99px;font-size:12.5px;font-weight:700;cursor:pointer;white-space:nowrap;transition:all .18s;}

        .csp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(272px,1fr));gap:16px;}
        .csp-card{position:relative;cursor:pointer;border-radius:20px;padding:20px;overflow:hidden;
          background:linear-gradient(155deg,rgba(255,255,255,.075),rgba(255,255,255,.028));
          border:1.5px solid rgba(255,255,255,.09);backdrop-filter:blur(14px);
          animation:csp-rise .42s cubic-bezier(.2,.85,.3,1) both;
          transition:transform .24s cubic-bezier(.2,.85,.3,1),box-shadow .24s,border-color .24s;
          transform-style:preserve-3d;}
        .csp-card::before{content:"";position:absolute;inset:0;opacity:0;transition:opacity .28s;pointer-events:none;
          background:radial-gradient(360px 180px at 50% 0%,var(--wash),transparent 72%);}
        .csp-card:hover::before,.csp-card.on::before{opacity:1;}
        .csp-card:hover{transform:translateY(-6px) scale(1.018);border-color:var(--edge);
          box-shadow:0 24px 52px rgba(0,0,0,.5),0 0 44px var(--glow);}
        .csp-card:focus-visible{outline:3px solid var(--edge);outline-offset:3px;}
        .csp-card.on{border-color:var(--edge);box-shadow:0 18px 44px rgba(0,0,0,.46),0 0 0 2px var(--edge),0 0 46px var(--glow);}
        @keyframes csp-rise{from{opacity:0;transform:translateY(16px) scale(.96);}to{opacity:1;transform:none;}}

        .csp-mono{width:56px;height:56px;border-radius:17px;display:flex;align-items:center;justify-content:center;
          font-size:19px;font-weight:800;letter-spacing:.4px;color:#fff;margin-bottom:15px;position:relative;
          box-shadow:0 10px 26px var(--glow),inset 0 1px 0 rgba(255,255,255,.32);}
        .csp-name{font-size:16.5px;font-weight:750;color:#f4f1ff;line-height:1.32;margin-bottom:7px;letter-spacing:-.2px;}
        .csp-by{display:flex;align-items:center;gap:7px;margin-bottom:14px;}
        .csp-byav{width:19px;height:19px;border-radius:99px;background:rgba(255,255,255,.12);display:flex;align-items:center;
          justify-content:center;font-size:9.5px;font-weight:800;color:#c9c1e8;flex-shrink:0;}
        .csp-byname{font-size:12.5px;color:#9b92bd;}
        .csp-meta{display:flex;gap:7px;flex-wrap:wrap;}
        .csp-tag{font-size:11px;font-weight:700;padding:5px 11px;border-radius:99px;}
        .csp-check{position:absolute;top:17px;right:17px;width:27px;height:27px;border-radius:99px;
          display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:800;color:#fff;
          animation:csp-pop .32s cubic-bezier(.2,1.5,.4,1);}
        @keyframes csp-pop{from{transform:scale(0) rotate(-90deg);}to{transform:none;}}
        .csp-ghost{position:absolute;top:17px;right:17px;width:27px;height:27px;border-radius:99px;
          border:1.5px dashed rgba(255,255,255,.24);transition:all .2s;}
        .csp-card:hover .csp-ghost{border-color:var(--edge);transform:scale(1.1);}

        .csp-tray{position:fixed;left:0;right:0;bottom:0;z-index:40;padding:16px 24px;
          background:linear-gradient(180deg,rgba(13,10,26,.5),rgba(13,10,26,.94));
          backdrop-filter:blur(20px);border-top:1px solid rgba(255,255,255,.1);}
        .csp-trayin{max-width:1120px;margin:0 auto;display:flex;align-items:center;gap:16px;flex-wrap:wrap;}
        .csp-chip{display:inline-flex;align-items:center;gap:7px;font-size:12.5px;font-weight:650;padding:7px 13px;
          border-radius:99px;cursor:pointer;transition:all .16s;animation:csp-pop .26s ease;}
        .csp-chip:hover{transform:translateY(-1px);}
        .csp-go{padding:15px 34px;border-radius:15px;border:none;font-weight:750;font-size:15px;cursor:pointer;
          transition:transform .18s,box-shadow .18s,background .18s;white-space:nowrap;}
        .csp-go:not(:disabled):hover{transform:translateY(-2px);box-shadow:0 14px 36px rgba(124,58,237,.55);}
        .csp-go:disabled{cursor:not-allowed;}

        .csp-empty{text-align:center;padding:74px 24px;border-radius:22px;
          background:rgba(255,255,255,.035);border:1.5px dashed rgba(255,255,255,.13);}

        @media (max-width:640px){
          .csp-in{padding:0 18px;}
          .csp-grid{grid-template-columns:1fr;}
          .csp-go{width:100%;}
          .csp-trayin{gap:11px;}
        }
        @media (prefers-reduced-motion:reduce){
          .csp::before{animation:none;}
          .csp-card,.csp-check,.csp-chip{animation:none;}
          .csp-card:hover{transform:none;}
        }
      `}</style>

      <div className="csp-in" style={{ paddingTop:44 }}>
        <button className="csp-back" onClick={onBack}>← Back to your details</button>

        <div className="csp-step">
          <span className="csp-dot" />
          <span className="csp-steptext">Step 2 of 2 · Choose courses</span>
        </div>

        <h1 className="csp-h1">
          {studentName ? <>What are you here to <em>learn</em>, {studentName.split(" ")[0]}?</> : <>What are you here to <em>learn</em>?</>}
        </h1>
        <p className="csp-lead">
          Pick everything you want to join — you can choose more than one. Each request goes to that
          course's trainer for approval, and you'll get a notification the moment one comes back.
        </p>

        <div className="csp-controls">
          <div className="csp-searchwrap">
            <span className="csp-searchicon">⌕</span>
            <input className="csp-search" value={query} onChange={e => setQuery(e.target.value)}
              placeholder={`Search ${courses.length} course${courses.length === 1 ? "" : "s"} or trainers…`} />
          </div>
          {trainerNames.length > 1 && (
            <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
              <button className="csp-pill" style={pillStyle(trainerFilter === "all")} onClick={() => setTrainerFilter("all")}>
                All trainers
              </button>
              {trainerNames.map(([id, name]) => (
                <button key={id} className="csp-pill" style={pillStyle(trainerFilter === id)} onClick={() => setTrainerFilter(id)}>
                  {name}
                </button>
              ))}
            </div>
          )}
        </div>

        {error && (
          <div style={{ background:"rgba(239,68,68,.13)", border:"1.5px solid rgba(248,113,113,.36)", borderRadius:14, padding:"13px 17px", marginBottom:18 }}>
            <p style={{ color:"#fca5a5", fontSize:13.5, fontWeight:600 }}>{error}</p>
          </div>
        )}

        {visible.length === 0 ? (
          <div className="csp-empty">
            <div style={{ fontSize:40, marginBottom:14, opacity:.65 }}>{courses.length === 0 ? "🗓" : "⌕"}</div>
            <p style={{ fontSize:17, fontWeight:750, color:"#e8e3fa", marginBottom:8 }}>
              {courses.length === 0 ? "No courses are open for enrolment yet" : `Nothing matches "${query}"`}
            </p>
            <p style={{ fontSize:14, color:"#8f86b3", lineHeight:1.6 }}>
              {courses.length === 0
                ? "Check back once a trainer publishes one."
                : "Try a different word, or clear the trainer filter."}
            </p>
            {courses.length > 0 && (
              <button className="csp-pill" style={{ ...pillStyle(false), marginTop:18 }}
                onClick={() => { setQuery(""); setTrainerFilter("all"); }}>
                Clear filters
              </button>
            )}
          </div>
        ) : (
          <div className="csp-grid">
            {visible.map((c, i) => {
              const on = selectedIds.includes(c.id);
              const a = courseAccent(c.name);
              const tName = trainersMap[c.trainerId]?.name || "Unknown trainer";
              const dayCount = Array.isArray(c.planDays) ? c.planDays.length : 0;
              const weeks = dayCount > 0 ? Math.max(1, Math.round(dayCount / 5)) : 0;
              return (
                <div
                  key={c.id}
                  className={`csp-card${on ? " on" : ""}`}
                  role="checkbox" aria-checked={on} tabIndex={0}
                  onClick={() => toggle(c.id)}
                  onMouseEnter={() => setHovered(c.id)}
                  onMouseLeave={() => setHovered(null)}
                  onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(c.id); } }}
                  style={{
                    "--edge": a.edge, "--glow": `hsla(${a.hue ?? 268} 85% 60% / .3)`,
                    "--wash": `hsla(${a.hue ?? 268} 85% 62% / .16)`,
                    animationDelay: `${Math.min(i * 45, 420)}ms`,
                  }}
                >
                  {on
                    ? <span className="csp-check" style={{ background:`linear-gradient(135deg,${a.from},${a.to})`, boxShadow:`0 4px 16px hsla(${a.hue ?? 268} 85% 55% / .55)` }}>✓</span>
                    : <span className="csp-ghost" />}

                  <div className="csp-mono" style={{ background:`linear-gradient(140deg,${a.from},${a.to})` }}>
                    {courseMonogram(c.name)}
                  </div>

                  <p className="csp-name">{c.name}</p>
                  <div className="csp-by">
                    <span className="csp-byav">{(tName[0] || "?").toUpperCase()}</span>
                    <span className="csp-byname">{tName}</span>
                  </div>

                  <div className="csp-meta">
                    <span className="csp-tag" style={{ background:`hsla(${a.hue ?? 268} 70% 55% / .18)`, color:a.edge }}>
                      {dayCount > 0 ? `${dayCount} days` : "Starting soon"}
                    </span>
                    {weeks > 0 && (
                      <span className="csp-tag" style={{ background:"rgba(255,255,255,.07)", color:"#a79fc4" }}>
                        ≈{weeks} week{weeks > 1 ? "s" : ""}
                      </span>
                    )}
                    {on && (
                      <span className="csp-tag" style={{ background:"rgba(34,197,94,.17)", color:"#86efac" }}>Selected</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div className="csp-tray">
        <div className="csp-trayin">
          <div style={{ flex:"1 1 220px", minWidth:0 }}>
            {selectedCourses.length === 0 ? (
              <p style={{ fontSize:14, color:"#8f86b3" }}>Tap a course to add it — pick as many as you like.</p>
            ) : (
              <>
                <p style={{ fontSize:12.5, fontWeight:700, color:"#c4b5fd", marginBottom:7 }}>
                  {selectedCourses.length} selected{totalDays > 0 ? ` · ${totalDays} days of material` : ""}
                </p>
                <div style={{ display:"flex", gap:7, flexWrap:"wrap" }}>
                  {selectedCourses.slice(0, 4).map(c => {
                    const a = courseAccent(c.name);
                    return (
                      <span key={c.id} className="csp-chip" onClick={() => toggle(c.id)} title="Remove"
                        style={{ background:`hsla(${a.hue ?? 268} 70% 55% / .2)`, color:a.edge, border:`1px solid ${a.edge}` }}>
                        {c.name} <span style={{ opacity:.7 }}>×</span>
                      </span>
                    );
                  })}
                  {selectedCourses.length > 4 && (
                    <span style={{ fontSize:12.5, color:"#8f86b3", fontWeight:650, alignSelf:"center" }}>
                      +{selectedCourses.length - 4} more
                    </span>
                  )}
                </div>
              </>
            )}
          </div>

          <button
            className="csp-go"
            onClick={onSubmit}
            disabled={loading || selectedCourses.length === 0}
            style={{
              background: selectedCourses.length === 0 ? "rgba(255,255,255,.08)" : "linear-gradient(135deg,#8b5cf6,#6d28d9)",
              color: selectedCourses.length === 0 ? "#6f6592" : "#fff",
              boxShadow: selectedCourses.length === 0 ? "none" : "0 8px 26px rgba(124,58,237,.45)",
            }}>
            {loading ? "Creating your account…" : selectedCourses.length === 0 ? "Choose at least one" : `Create account · ${selectedCourses.length}`}
          </button>
        </div>
      </div>
    </div>
  );
}

function pillStyle(active) {
  return {
    border: `1.5px solid ${active ? "#8b5cf6" : "rgba(255,255,255,.12)"}`,
    background: active ? "linear-gradient(135deg,#8b5cf6,#6d28d9)" : "rgba(255,255,255,.05)",
    color: active ? "#fff" : "#a79fc4",
    boxShadow: active ? "0 6px 20px rgba(124,58,237,.4)" : "none",
  };
}


function LoginScreen({ onLogin, sb, initialMode = "select", onBackToLanding }) {
  const [mode, setMode] = useState(initialMode);
  const [trainerUsername, setTrainerUsername] = useState("");
  const [trainerPass, setTrainerPass]         = useState("");
  const [newTrainerName, setNewTrainerName]   = useState("");
  const [newTrainerUsername, setNewTrainerUsername] = useState("");
  const [newTrainerPass, setNewTrainerPass]   = useState("");
  const [studentEmail, setStudentEmail]       = useState("");
  const [studentName, setStudentName]         = useState("");
  const [studentPassword, setStudentPassword] = useState(""); // FIX #3
  const [studentCourseIds, setStudentCourseIds] = useState([]); // multi-course selection
  const [error, setError]   = useState("");
  const [loading, setLoading] = useState(false);
  const [allCourses, setAllCourses] = useState([]);
  const [trainersMap, setTrainersMap] = useState({});


  useEffect(() => {
    if (!sb) return;
    // Load trainers first so we can hide any trainer who isn't currently
    // approved (pending OR revoked) — their name & courses must never show
    // during registration. Re-runs on every mount, so re-approval reappears.
    sbGetTrainers(sb).then(trainers => {
      const m = {};
      trainers.forEach(t => { m[t.id] = t; });
      setTrainersMap(m);
      sbGetCourses(sb).then(courses => {
        const visible = courses.map(dbRowToCourse).filter(c => m[c.trainerId]?.approved === true);
        setAllCourses(visible);
      }).catch(() => {});
    }).catch(() => {});
  }, [sb]);

  const handleTrainerLogin = async () => {
    setError(""); setLoading(true);
    try {
      if (!trainerUsername.trim() || !trainerPass.trim()) throw new Error("Enter username and password");
      // ── Admin hardcoded login (no DB lookup needed) ──
      if (trainerUsername.trim() === ADMIN_USERNAME && trainerPass === ADMIN_PASSWORD) {
        saveAuthState({ ...ADMIN_USER, loginTime: new Date().toISOString() });
        onLogin();
        setLoading(false);
        return;
      }
      if (!sb) throw new Error("Database not configured — check VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in .env");
      const trainer = await sbLoginTrainer(sb, trainerUsername.trim(), trainerPass);
      if (!trainer) throw new Error("Invalid username or password");
      saveAuthState({ role: "trainer", id: trainer.id, name: trainer.name, username: trainer.username, loginTime: new Date().toISOString() });
      onLogin();
    } catch (e) { setError(e.message); }
    setLoading(false);
  };

  const handleTrainerRegister = async () => {
    setError(""); setLoading(true);
    try {
      if (!newTrainerName.trim() || !newTrainerUsername.trim() || !newTrainerPass.trim()) throw new Error("Fill in all fields");
      if (!sb) throw new Error("Database not configured — check VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in .env");
      await sbRegisterTrainer(sb, newTrainerName, newTrainerUsername, newTrainerPass);
      // Do NOT auto-login — trainer must wait for admin approval
      setError("");
      setNewTrainerName(""); setNewTrainerUsername(""); setNewTrainerPass("");
      setMode("trainer-pending");
    } catch (e) { setError(e.message); }
    setLoading(false);
  };

  const handleStudentRegister = async () => {
    setError(""); setLoading(true);
    try {
      if (!studentName.trim() || !studentEmail.trim()) throw new Error("Fill in all fields");
      // FIX #3: require a password on registration
      if (!studentPassword.trim() || studentPassword.trim().length < 6) throw new Error("Password must be at least 6 characters");
      if (!studentCourseIds.length) throw new Error("Please select at least one course to enroll in");
      // FIX #14: filter server-side by email — don't fetch all students
      const existingRows = await sb.select("lms_students", `email=eq.${encodeURIComponent(studentEmail.trim())}&limit=1`);
      if (existingRows && existingRows.length > 0) throw new Error("Email already registered");
      // Use the first selected course's trainer as the primary trainer (trainer_id column)
      // FIX: also collect ALL unique trainer IDs from selected courses so every trainer
      // can see this student's request, not just the first-course trainer.
      const firstCourse = allCourses.find(c => c.id === studentCourseIds[0]);
      if (!firstCourse?.trainerId) throw new Error("Could not determine trainer for the selected course");
      const newId = generateId();
      // FIX #3: hash the password before storing
      const passwordHash = await hashPassword(studentPassword.trim(), newId);
      // Build pendingCourseIds with trainer info embedded so each trainer's query
      // can find this student even if trainer_id points to a different trainer.
      const pendingCourseIds = studentCourseIds.map(cid => {
        const course = allCourses.find(c => c.id === cid);
        return {
          courseId: cid,
          courseName: course?.name || "",
          trainerId: course?.trainerId || "",
          requestedAt: new Date().toISOString(),
        };
      });
      const newStudent = {
        id: newId,
        name: studentName.trim(),
        email: studentEmail.trim(),
        passwordHash,
        // trainer_id = primary trainer (first selected course) — used for indexed queries
        trainerId: firstCourse.trainerId,
        approved: false,
        pendingCourseIds,
        enrolledCourseIds: [],
        // Keep legacy single-course fields so old code paths still work
        requestedCourseId: studentCourseIds[0],
        requestedCourseName: firstCourse?.name || "",
        requestedAt: new Date().toISOString(),
        createdAt: new Date().toISOString(),
      };
      await sbSaveStudent(sb, newStudent);
      alert(`✅ Registered for ${studentCourseIds.length} course(s)! Wait for trainer approval.`);
      setMode("select");
      setStudentName(""); setStudentEmail(""); setStudentCourseIds([]); setStudentPassword("");
    } catch (e) { setError(e.message); }
    setLoading(false);
  };

  // FIX #3: student login now verifies password hash
  const handleStudentLogin = async () => {
    setError(""); setLoading(true);
    try {
      if (!studentEmail.trim()) throw new Error("Enter email");
      if (!studentPassword.trim()) throw new Error("Enter password");
      // FIX #14: server-side filter, not full table scan
      const rows = await sb.select("lms_students", `email=eq.${encodeURIComponent(studentEmail.trim())}&limit=1`);
      if (!rows || rows.length === 0) throw new Error("Email not found");
      const student = dbRowToStudent(rows[0]);
      // FIX 8: Verify password with PBKDF2; transparently rehash legacy SHA-256 accounts
      if (student.passwordHash) {
        const { ok, needsRehash } = await verifyPassword(studentPassword.trim(), student.id, student.passwordHash);
        if (!ok) throw new Error("Incorrect password");
        if (needsRehash) {
          const newHash = await hashPassword(studentPassword.trim(), student.id);
          await sb.update("lms_students", `id=eq.${encodeURIComponent(student.id)}`, { password_hash: newHash })
            .catch(() => {}); // non-fatal
        }
      }
      const enrolled = getStudentEnrolledCourses(student);
      const hasApproved = student.approved || enrolled.length > 0;
      if (!hasApproved) throw new Error("Pending trainer approval");
      saveAuthState({ role: "student", id: student.id, name: student.name, email: student.email, loginTime: new Date().toISOString() });
      onLogin();
    } catch (e) { setError(e.message); }
    setLoading(false);
  };



  // The catalogue takes over the whole viewport — it is a page in its own
  // right, not a scroll box wedged into the sign-up card.
  if (mode === "register-courses") {
    return (
      <CourseSelectPage
        courses={allCourses}
        trainersMap={trainersMap}
        selectedIds={studentCourseIds}
        setSelectedIds={setStudentCourseIds}
        studentName={studentName}
        loading={loading}
        error={error}
        onBack={() => { setError(""); setMode("register"); }}
        onSubmit={handleStudentRegister}
      />
    );
  }

  // ── Derived state for new unified design ──
  const isRegisterMode = mode === "register" || mode === "trainer-register";
  const selectedRole   = mode === "trainer" || mode === "trainer-register" || mode === "trainer-pending" ? "trainer" : mode === "student" || mode === "register" ? "student" : null;

  // Shared input style
  const inputSt = {
    width: "100%", padding: "12px 16px 12px 44px", border: "1.5px solid #e2e8f0",
    borderRadius: 50, fontSize: 14, color: "#2d3748", outline: "none",
    background: "#fafafa", boxSizing: "border-box", transition: "border-color .2s",
  };
  const inputWrap = { position: "relative", width: "100%" };
  const iconSt = { position: "absolute", left: 16, top: "50%", transform: "translateY(-50%)", color: "#a0aec0", fontSize: 15, pointerEvents: "none" };

  return (
    <div style={{
      minHeight: "100vh",
      background: "linear-gradient(135deg, #c4b5fd 0%, #a78bfa 40%, #7c3aed 100%)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      padding: 20,
      fontFamily: "'Segoe UI','Helvetica Neue',system-ui,sans-serif",
    }}>
      {/* Card */}
      <div style={{
        display: "flex",
        borderRadius: 24,
        overflow: "hidden",
        width: "100%",
        maxWidth: mode === "register" ? 860 : 780,
        minHeight: 520,
        boxShadow: "0 32px 80px rgba(109,40,217,.35)",
        background: "white",
        transition: "max-width .3s",
      }}>

        {/* ── LEFT PANEL ── */}
        <div style={{
          flex: "0 0 42%",
          background: "linear-gradient(160deg, #7c3aed 0%, #6d28d9 45%, #5b21b6 100%)",
          padding: "48px 36px",
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          position: "relative",
          overflow: "hidden",
        }}>
          {/* Decorative blobs */}
          <div style={{ position:"absolute", top:-60, right:-60, width:180, height:180, borderRadius:"50%", background:"rgba(255,255,255,.08)" }} />
          <div style={{ position:"absolute", bottom:-40, left:-40, width:140, height:140, borderRadius:"50%", background:"rgba(255,255,255,.06)" }} />
          {/* Wavy lines SVG */}
          <svg style={{ position:"absolute", bottom:60, right:0, opacity:.18, width:140 }} viewBox="0 0 140 120" fill="none">
            <path d="M10 100 C 30 70, 50 130, 70 100 S 110 70, 130 100" stroke="white" strokeWidth="2" fill="none"/>
            <path d="M10 80 C 30 50, 50 110, 70 80 S 110 50, 130 80"  stroke="white" strokeWidth="2" fill="none"/>
            <path d="M10 60 C 30 30, 50 90,  70 60 S 110 30, 130 60"  stroke="white" strokeWidth="2" fill="none"/>
          </svg>
          {/* Dots grid */}
          <div style={{ position:"absolute", top:24, right:24, display:"grid", gridTemplateColumns:"repeat(4,8px)", gap:5, opacity:.4 }}>
            {Array.from({length:16}).map((_,i)=><div key={i} style={{width:4,height:4,borderRadius:"50%",background:"white"}}/>)}
          </div>
          {/* Plus signs */}
          <div style={{ position:"absolute", top:32, left:32, color:"rgba(255,255,255,.4)", fontSize:20, fontWeight:300 }}>+</div>
          <div style={{ position:"absolute", bottom:100, left:48, color:"rgba(255,255,255,.3)", fontSize:20, fontWeight:300 }}>+</div>
          {/* Circle outlines */}
          <div style={{ position:"absolute", top:120, left:24, width:24, height:24, borderRadius:"50%", border:"2px solid rgba(255,255,255,.35)" }} />
          <div style={{ position:"absolute", bottom:40, left:28, width:18, height:18, borderRadius:"50%", border:"2px solid rgba(255,255,255,.3)" }} />

          <div style={{ position:"relative", zIndex:1 }}>
            <h2 style={{ color:"white", fontSize:33, fontWeight:600, letterSpacing:".08em", textTransform:"uppercase", margin:"0 0 24px 0", opacity:.8 }}>LMS Portal</h2>
          </div>
          <div style={{ position:"relative", zIndex:1 }}>
            <h1 style={{ color:"white", fontSize:26, fontWeight:800, margin:"0 0 12px 0", lineHeight:1.25 }}>
              {mode === "trainer-pending" ? "Almost there!" : isRegisterMode ? "Join us today!" : "Welcome back!"}
            </h1>
            <p style={{ color:"rgba(255,255,255,.75)", fontSize:13.5, lineHeight:1.7, margin:0 }}>
              {mode === "trainer-pending"
                ? "Your account is under review. An admin will approve it shortly."
                : isRegisterMode
                  ? "Create your account and start your learning journey."
                  : "Sign in to access your courses, progress, and more."}
            </p>
          </div>
        </div>

        {/* ── RIGHT PANEL ── */}
        <div style={{ flex:1, padding:"44px 44px", display:"flex", flexDirection:"column", justifyContent:"center", overflowY:"auto" }}>

          {/* Trainer-pending state */}
          {mode === "trainer-pending" && (
            <div style={{ display:"flex", flexDirection:"column", gap:16, textAlign:"center" }}>
              <div style={{ fontSize:52 }}>⏳</div>
              <p style={{ fontWeight:800, fontSize:20, color:"#1a202c", margin:0 }}>Account Created!</p>
              <p style={{ fontSize:13.5, color:"#64748b", lineHeight:1.7, margin:0 }}>
                Your trainer account has been submitted. An admin will review and approve it shortly. Once approved you can sign in normally.
              </p>
              <div style={{ background:"#f0fdf4", border:"1px solid #bbf7d0", borderRadius:10, padding:"12px 16px", fontSize:13, color:"#166534", textAlign:"left", lineHeight:1.6 }}>
                ✅ Account registered successfully<br/>
                🔒 Status: <strong>Pending admin approval</strong><br/>
                📧 Contact admin if not approved within 24 hrs
              </div>
              <button onClick={()=>setMode("trainer")} style={{ padding:"13px 0", background:"linear-gradient(135deg,#7c3aed,#6d28d9)", color:"white", border:"none", borderRadius:50, fontWeight:700, cursor:"pointer", fontSize:14 }}>Go to Sign In</button>
              <button onClick={()=>setMode("select")} style={{ padding:"11px 0", background:"transparent", color:"#7c3aed", border:"1.5px solid #7c3aed", borderRadius:50, fontWeight:600, cursor:"pointer", fontSize:13 }}>← Back to Home</button>
            </div>
          )}

          {/* All non-pending modes */}
          {mode !== "trainer-pending" && (
            <>
              <h2 style={{ fontSize:24, fontWeight:800, color:"#1a202c", margin:"0 0 6px 0" }}>
                {isRegisterMode ? "Create Account" : "Sign In"}
              </h2>
              <p style={{ color:"#94a3b8", fontSize:13, margin:"0 0 24px 0" }}>
                {isRegisterMode ? "Fill in the details below to get started." : "Enter your credentials to continue."}
              </p>

              {error && (
                <div style={{ background:"#fff1f2", color:"#be123c", padding:"10px 14px", borderRadius:10, marginBottom:16, fontSize:13, border:"1px solid #fecdd3" }}>{error}</div>
              )}

              {/* ── ROLE SELECTOR (shown on select / trainer / student / register) ── */}
              {(mode === "select" || mode === "trainer" || mode === "student" || mode === "register") && (
                <div style={{ display:"flex", gap:10, marginBottom:22 }}>
                  {[
                    { key:"trainer", label:"Trainer", icon:"👨‍🏫" },
                    { key:"student", label:"Student", icon:"👨‍🎓" },
                  ].map(r => {
                    const active = selectedRole === r.key;
                    return (
                      <button key={r.key}
                        onClick={() => {
                          setError("");
                          if (r.key === "trainer") setMode(mode === "register" || mode === "select" ? "trainer" : "trainer");
                          else setMode(mode === "register" ? "register" : "student");
                        }}
                        style={{
                          flex:1, padding:"10px 0", borderRadius:50, fontWeight:600, fontSize:13.5,
                          cursor:"pointer", transition:"all .18s",
                          background: active ? "linear-gradient(135deg,#7c3aed,#6d28d9)" : "#f1f5f9",
                          color: active ? "white" : "#64748b",
                          border: active ? "none" : "1.5px solid #e2e8f0",
                          boxShadow: active ? "0 4px 14px rgba(124,58,237,.35)" : "none",
                        }}
                      >{r.icon} {r.label}</button>
                    );
                  })}
                </div>
              )}

              {/* ── TRAINER LOGIN ── */}
              {mode === "trainer" && (
                <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
                  <div style={inputWrap}>
                    <span style={iconSt}>👤</span>
                    <input type="text" value={trainerUsername} onChange={e=>setTrainerUsername(e.target.value)} placeholder="Username" style={inputSt} />
                  </div>
                  <div style={inputWrap}>
                    <span style={iconSt}>🔒</span>
                    <input type="password" value={trainerPass} onChange={e=>setTrainerPass(e.target.value)} placeholder="Password" style={inputSt} onKeyDown={e=>e.key==="Enter"&&handleTrainerLogin()} />
                  </div>
                  <button onClick={handleTrainerLogin} disabled={loading} style={{ padding:"13px 0", background:"linear-gradient(135deg,#7c3aed,#6d28d9)", color:"white", border:"none", borderRadius:50, fontWeight:700, cursor:"pointer", fontSize:14, marginTop:4, boxShadow:"0 4px 16px rgba(124,58,237,.4)" }}>
                    {loading ? "Signing in…" : "Sign In"}
                  </button>
                  <p style={{ textAlign:"center", fontSize:13, color:"#64748b", margin:0 }}>
                    New trainer?{" "}
                    <span onClick={()=>{setError("");setMode("trainer-register");}} style={{ color:"#7c3aed", fontWeight:600, cursor:"pointer" }}>Create an Account</span>
                  </p>
                </div>
              )}

              {/* ── STUDENT LOGIN ── */}
              {mode === "student" && (
                <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
                  <div style={inputWrap}>
                    <span style={iconSt}>✉️</span>
                    <input type="email" value={studentEmail} onChange={e=>setStudentEmail(e.target.value)} placeholder="your@email.com" style={inputSt} />
                  </div>
                  <div style={inputWrap}>
                    <span style={iconSt}>🔒</span>
                    {/* FIX #3: password required for student login */}
                    <input type="password" value={studentPassword} onChange={e=>setStudentPassword(e.target.value)} placeholder="Password" style={inputSt} onKeyDown={e=>e.key==="Enter"&&handleStudentLogin()} />
                  </div>
                  <button onClick={handleStudentLogin} disabled={loading} style={{ padding:"13px 0", background:"linear-gradient(135deg,#7c3aed,#6d28d9)", color:"white", border:"none", borderRadius:50, fontWeight:700, cursor:"pointer", fontSize:14, marginTop:4, boxShadow:"0 4px 16px rgba(124,58,237,.4)" }}>
                    {loading ? "Signing in…" : "Sign In"}
                  </button>
                  <p style={{ textAlign:"center", fontSize:13, color:"#64748b", margin:0 }}>
                    New here?{" "}
                    <span onClick={()=>{setError("");setMode("register");}} style={{ color:"#7c3aed", fontWeight:600, cursor:"pointer" }}>Create an Account</span>
                  </p>
                </div>
              )}

              {/* ── SELECT (initial state — role picker handles navigation) ── */}
              {mode === "select" && (
                <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
                  <p style={{ textAlign:"center", color:"#94a3b8", fontSize:13, margin:0 }}>Select a role above to get started.</p>
                </div>
              )}

              {/* ── TRAINER REGISTER ── */}
              {mode === "trainer-register" && (
                <div style={{ display:"flex", flexDirection:"column", gap:13 }}>
                  <div style={inputWrap}>
                    <span style={iconSt}>👤</span>
                    <input type="text" value={newTrainerName} onChange={e=>setNewTrainerName(e.target.value)} placeholder="Full Name" style={inputSt} />
                  </div>
                  <div style={inputWrap}>
                    <span style={iconSt}>🪪</span>
                    <input type="text" value={newTrainerUsername} onChange={e=>setNewTrainerUsername(e.target.value)} placeholder="Username (unique)" style={inputSt} />
                  </div>
                  <div style={inputWrap}>
                    <span style={iconSt}>🔒</span>
                    <input type="password" value={newTrainerPass} onChange={e=>setNewTrainerPass(e.target.value)} placeholder="Password" style={inputSt} />
                  </div>
                  <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:10, padding:"9px 14px", fontSize:12, color:"#92400e", lineHeight:1.6 }}>
                    🔒 New trainer accounts require admin approval before login is granted.
                  </div>
                  <button onClick={handleTrainerRegister} disabled={loading} style={{ padding:"13px 0", background:"linear-gradient(135deg,#7c3aed,#6d28d9)", color:"white", border:"none", borderRadius:50, fontWeight:700, cursor:"pointer", fontSize:14, boxShadow:"0 4px 16px rgba(124,58,237,.4)" }}>
                    {loading ? "Creating…" : "Request Trainer Account"}
                  </button>
                  <p style={{ textAlign:"center", fontSize:13, color:"#64748b", margin:0 }}>
                    Already have an account?{" "}
                    <span onClick={()=>{setError("");setMode("trainer");}} style={{ color:"#7c3aed", fontWeight:600, cursor:"pointer" }}>Sign In</span>
                  </p>
                </div>
              )}

              {/* ── STUDENT REGISTER ── */}
              {mode === "register" && (
                <div style={{ display:"flex", flexDirection:"column", gap:13 }}>
                  <div style={inputWrap}>
                    <span style={iconSt}>👤</span>
                    <input type="text" value={studentName} onChange={e=>setStudentName(e.target.value)} placeholder="Full Name" style={inputSt} />
                  </div>
                  <div style={inputWrap}>
                    <span style={iconSt}>✉️</span>
                    <input type="email" value={studentEmail} onChange={e=>setStudentEmail(e.target.value)} placeholder="your@email.com" style={inputSt} />
                  </div>
                  <div style={inputWrap}>
                    <span style={iconSt}>🔒</span>
                    {/* FIX #3: require password at registration */}
                    <input type="password" value={studentPassword} onChange={e=>setStudentPassword(e.target.value)} placeholder="Choose a password (min 6 chars)" style={inputSt} />
                  </div>

                  {/* Courses are chosen on their own page — see CourseSelectPage */}
                  <div
                    onClick={() => { setError(""); setMode("register-courses"); }}
                    role="button" tabIndex={0}
                    onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setError(""); setMode("register-courses"); } }}
                    style={{
                      border:`1.5px solid ${studentCourseIds.length ? "#c4b5fd" : "#e2e8f0"}`,
                      background: studentCourseIds.length ? "#faf8ff" : "#fafafa",
                      borderRadius:16, padding:"14px 16px", cursor:"pointer",
                      display:"flex", alignItems:"center", gap:12, transition:"all .18s",
                    }}>
                    <div style={{
                      width:38, height:38, borderRadius:11, flexShrink:0,
                      background:"linear-gradient(135deg,#8b5cf6,#6d28d9)",
                      display:"flex", alignItems:"center", justifyContent:"center", fontSize:17,
                    }}>📚</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <p style={{ fontSize:13.5, fontWeight:700, color:"#2e1065" }}>
                        {studentCourseIds.length === 0
                          ? "Choose your courses"
                          : `${studentCourseIds.length} course${studentCourseIds.length > 1 ? "s" : ""} selected`}
                      </p>
                      <p style={{ fontSize:12, color:"#8b7fa8", marginTop:2, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                        {studentCourseIds.length === 0
                          ? `Browse ${allCourses.length} available course${allCourses.length === 1 ? "" : "s"}`
                          : allCourses.filter(c => studentCourseIds.includes(c.id)).map(c => c.name).join(", ")}
                      </p>
                    </div>
                    <span style={{ color:"#7c3aed", fontWeight:700, fontSize:18, flexShrink:0 }}>›</span>
                  </div>

                  <button
                    onClick={() => {
                      // Validate the details here so nobody fills in a whole
                      // catalogue page only to be sent back for a typo.
                      if (!studentName.trim() || !studentEmail.trim()) { setError("Fill in your name and email first"); return; }
                      if (!studentPassword.trim() || studentPassword.trim().length < 6) { setError("Password must be at least 6 characters"); return; }
                      setError("");
                      setMode("register-courses");
                    }}
                    disabled={loading}
                    style={{ padding:"13px 0", background:"linear-gradient(135deg,#7c3aed,#6d28d9)", color:"white", border:"none", borderRadius:50, fontWeight:700, cursor:"pointer", fontSize:14, boxShadow:"0 4px 16px rgba(124,58,237,.4)" }}>
                    {studentCourseIds.length ? "Review courses & finish" : "Continue to courses"}
                  </button>
                  <p style={{ textAlign:"center", fontSize:13, color:"#64748b", margin:0 }}>
                    Already registered?{" "}
                    <span onClick={()=>{setError("");setMode("student");}} style={{ color:"#7c3aed", fontWeight:600, cursor:"pointer" }}>Sign In</span>
                  </p>
                </div>
              )}

              {/* ── Back to Landing link ── */}
              {onBackToLanding && (
                <p style={{ textAlign:"center", fontSize:12.5, color:"#94a3b8", marginTop:18, marginBottom:0 }}>
                  <span onClick={onBackToLanding} style={{ color:"#7c3aed", fontWeight:600, cursor:"pointer" }}>
                    ← Back to Home
                  </span>
                </p>
              )}

            </>
          )}
        </div>
      </div>
    </div>
  );
}


// Batch options available in the dropdown — trainer can also type a custom label
const BATCH_OPTIONS = ["Morning", "Evening", "Batch A", "Batch B", "Batch 1", "Batch 2", "Weekend", "Online"];
// Deterministic color per known label; unknown labels get a hash-based color in the UI
const BATCH_COLORS = {
  "Morning":  "#f59e0b",
  "Evening":  "#8B5CF6",
  "Batch A":  "#3b82f6",
  "Batch B":  "#10b981",
  "Batch 1":  "#3b82f6",
  "Batch 2":  "#10b981",
  "Weekend":  "#ef4444",
  "Online":   "#06b6d4",
};
// Returns a stable color for any batch label string
function batchLabelColor(label) {
  if (!label) return "#94a3b8";
  if (BATCH_COLORS[label]) return BATCH_COLORS[label];
  // Hash-based fallback for custom names
  let h = 0; for (let i = 0; i < label.length; i++) h = (h * 31 + label.charCodeAt(i)) & 0xFFFFFF;
  return "#" + (h & 0x7F7FFF | 0x404040).toString(16).padStart(6, "0");
}

/* ═══════════════════════════════════════════════════════════════════
   TRAINER ENROLLMENTS — Supabase-backed
═══════════════════════════════════════════════════════════════════ */
function TrainerEnrollments({ courseId, courseName, trainerId, sb, onClose }) {
  const [students, setStudents] = useState([]);
  const [allCourses, setAllCourses] = useState([]);
  const [addCourseStudentId, setAddCourseStudentId] = useState(null);
  const [addCourseId, setAddCourseId]               = useState("");
  const [loading, setLoading] = useState(true);
  // Batch editing: { [studentId]: draftLabel }
  const [batchDraft, setBatchDraft]   = useState({});
  const [batchSaving, setBatchSaving] = useState({});

  const load = async () => {
    setLoading(true);
    try {
      // Use sbGetStudentsForCourse so cross-trainer requests appear here too.
      // (trainer_id-only queries miss students whose primary trainer differs.)
      const students = await sbGetStudentsForCourse(sb, courseId, trainerId);
      setStudents(students);
      const courses = await sbGetCoursesByTrainer(sb, trainerId);
      setAllCourses(courses);
    } catch(e) { console.error(e); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const pending = students.filter(s => {
    const inPending = Array.isArray(s.pendingCourseIds) && s.pendingCourseIds.some(p => p.courseId === courseId);
    const legacyPending = !s.approved && s.requestedCourseId === courseId && !Array.isArray(s.pendingCourseIds);
    return inPending || legacyPending;
  });

  const approved = students.filter(s => {
    const inEnrolled = Array.isArray(s.enrolledCourseIds) && s.enrolledCourseIds.some(e => e.courseId === courseId);
    const legacyApproved = s.approved && s.requestedCourseId === courseId && !Array.isArray(s.enrolledCourseIds);
    return inEnrolled || legacyApproved;
  });

  const handleApprove = async (studentId) => {
    const s = students.find(x => x.id === studentId);
    if (!s) return;
    const pendingEntry = Array.isArray(s.pendingCourseIds) ? s.pendingCourseIds.find(p => p.courseId === courseId) : { courseId, courseName: s.requestedCourseName || courseName };
    const newEnrolled = [...(s.enrolledCourseIds || [])];
    if (!newEnrolled.some(e => e.courseId === courseId)) {
      newEnrolled.push({ courseId, courseName: pendingEntry?.courseName || courseName, approvedAt: new Date().toISOString() });
    }
    const newPending = Array.isArray(s.pendingCourseIds) ? s.pendingCourseIds.filter(p => p.courseId !== courseId) : [];
    const updated = { ...s, enrolledCourseIds: newEnrolled, pendingCourseIds: newPending, approved: true, approvedAt: new Date().toISOString(), requestedCourseId: s.requestedCourseId || courseId, requestedCourseName: s.requestedCourseName || courseName };
    await sbSaveStudent(sb, updated);
    // Tell the student — reaches them on whatever device they open next.
    sbCreateNotification(sb, {
      studentId: s.id,
      courseId,
      type: "enrollment_approved",
      title: `You're in: ${pendingEntry?.courseName || courseName}`,
      body: "Your enrolment was approved. Open the course to start.",
    }).catch(() => {});
    load();
  };

  const handleReject = async (studentId) => {
    const s = students.find(x => x.id === studentId);
    if (!s) return;
    // Strip this course from both arrays (a student could appear in pending OR enrolled here)
    const newPending  = Array.isArray(s.pendingCourseIds)  ? s.pendingCourseIds.filter(p  => p.courseId  !== courseId) : [];
    const newEnrolled = Array.isArray(s.enrolledCourseIds) ? s.enrolledCourseIds.filter(e => e.courseId  !== courseId) : [];
    const hasOtherPending    = newPending.length > 0;
    const hasOtherEnrolled   = newEnrolled.length > 0;
    const hasLegacyElsewhere = s.approved && s.requestedCourseId && s.requestedCourseId !== courseId;
    // After ALTER TABLE all students have JSONB arrays — !Array.isArray is always false.
    // Old code: !hasPending && !hasEnrolled && !Array.isArray(s.pendingCourseIds)
    // That last clause was ALWAYS false → single-course students were never deleted (zombie rows).
    // Fixed: delete when truly nothing remains anywhere.
    if (!hasOtherPending && !hasOtherEnrolled && !hasLegacyElsewhere) {
      await sbDeleteStudent(sb, studentId);
    } else {
      await sbSaveStudent(sb, { ...s, pendingCourseIds: newPending, enrolledCourseIds: newEnrolled });
    }
    load();
  };

  const handleRevoke = async (studentId) => {
    const s = students.find(x => x.id === studentId);
    if (!s) return;
    const newEnrolled = Array.isArray(s.enrolledCourseIds) ? s.enrolledCourseIds.filter(e => e.courseId !== courseId) : [];
    await sbSaveStudent(sb, { ...s, enrolledCourseIds: newEnrolled });
    load();
  };

  const handleAddCourseEnrollment = async () => {
    if (!addCourseStudentId || !addCourseId) return;
    const target = allCourses.find(c => c.id === addCourseId);
    if (!target) return;
    const s = students.find(x => x.id === addCourseStudentId);
    if (!s) return;
    const newEnrolled = [...(s.enrolledCourseIds || [])];
    if (!newEnrolled.some(e => e.courseId === addCourseId)) {
      newEnrolled.push({ courseId: addCourseId, courseName: target.name, approvedAt: new Date().toISOString() });
    }
    await sbSaveStudent(sb, { ...s, enrolledCourseIds: newEnrolled });
    setAddCourseStudentId(null); setAddCourseId("");
    load();
  };

  // Save batch label into the enrolledCourseIds entry for this course
  const handleSetBatch = async (studentId) => {
    const label = (batchDraft[studentId] ?? "").trim();
    const s = students.find(x => x.id === studentId);
    if (!s) return;
    setBatchSaving(p => ({ ...p, [studentId]: true }));
    try {
      const newEnrolled = (s.enrolledCourseIds || []).map(e =>
        e.courseId === courseId ? { ...e, batchLabel: label || null } : e
      );
      // Legacy path: no enrolledCourseIds array yet
      if (!Array.isArray(s.enrolledCourseIds) || !newEnrolled.some(e => e.courseId === courseId)) {
        newEnrolled.push({ courseId, courseName, batchLabel: label || null, approvedAt: new Date().toISOString() });
      }
      await sbSaveStudent(sb, { ...s, enrolledCourseIds: newEnrolled });
      // Update local state immediately so badge shows without full reload
      setStudents(prev => prev.map(x => x.id === studentId ? { ...x, enrolledCourseIds: newEnrolled } : x));
      setBatchDraft(p => { const n = { ...p }; delete n[studentId]; return n; });
    } catch (e) { alert("Failed to save batch: " + e.message); }
    finally { setBatchSaving(p => ({ ...p, [studentId]: false })); }
  };

  // Helper: get current saved batchLabel for a student in this course
  const getStudentBatch = (s) => {
    const entry = Array.isArray(s.enrolledCourseIds) ? s.enrolledCourseIds.find(e => e.courseId === courseId) : null;
    return entry?.batchLabel || "";
  };

  return (
    <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, background:"rgba(0,0,0,0.6)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:10000, padding:20 }}>
      <div style={{ background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", borderRadius:24, padding:30, maxWidth:720, width:"100%", maxHeight:"85vh", overflow:"auto", boxShadow:"20px 20px 48px #C4CDD9,-12px -12px 32px #fff", border:"1px solid #fff" }}>
        <h2 style={{ fontSize:22, fontWeight:700, marginBottom:4, color:"#1a202c" }}>📋 Student Enrollments</h2>
        {courseName && <p style={{ fontSize:14, color:"#764ba2", fontWeight:600, margin:"0 0 20px 0" }}>📚 {courseName}</p>}
        {loading ? <p style={{ color:"#94a3b8", textAlign:"center", padding:40 }}>Loading…</p> : (
          <>
            <div style={{ marginBottom:20 }}>
              <h3 style={{ color:"#f59e0b", marginBottom:10, fontSize:15 }}>⏳ Pending ({pending.length})</h3>
              {pending.length === 0 ? <p style={{ color:"#718096", fontSize:13 }}>No pending requests</p> : pending.map(s => (
                <div key={s.id} style={{ padding:12, background:"#fffbeb", border:"1px solid #fde68a", borderRadius:8, marginBottom:8, display:"flex", justifyContent:"space-between", alignItems:"center", gap:8 }}>
                  <div>
                    <p style={{ fontWeight:600, margin:"0 0 2px 0", color:"#1a202c", fontSize:14 }}>{s.name}</p>
                    <p style={{ fontSize:12, color:"#718096", margin:0 }}>{s.email}</p>
                  </div>
                  <div style={{ display:"flex", gap:8 }}>
                    <button onClick={()=>handleApprove(s.id)} style={{ padding:"6px 12px", background:"#22c55e", color:"white", border:"none", borderRadius:4, cursor:"pointer", fontSize:12, fontWeight:600 }}>Approve</button>
                    <button onClick={()=>handleReject(s.id)} style={{ padding:"6px 12px", background:"#ef4444", color:"white", border:"none", borderRadius:4, cursor:"pointer", fontSize:12, fontWeight:600 }}>Reject</button>
                  </div>
                </div>
              ))}
            </div>
            <div style={{ marginBottom:20 }}>
              <h3 style={{ color:"#22c55e", marginBottom:10, fontSize:15 }}>✅ Enrolled ({approved.length})</h3>
              {approved.length === 0 ? <p style={{ color:"#718096", fontSize:13 }}>No enrolled students</p> : approved.map(s => {
                const otherCourses    = (s.enrolledCourseIds||[]).filter(e=>e.courseId!==courseId);
                const savedBatch      = getStudentBatch(s);
                const isDrafting      = studentId => studentId in batchDraft;
                const draftVal        = batchDraft[s.id] ?? savedBatch;
                const isBatchEditing  = s.id in batchDraft;
                const batchColor      = savedBatch ? BATCH_COLORS[savedBatch] || "#8B5CF6" : null;
                return (
                  <div key={s.id} style={{ padding:12, background:"#f0fdf4", border:"1px solid #bbf7d0", borderRadius:8, marginBottom:8 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:8 }}>
                      <div style={{ flex:1 }}>
                        <div style={{ display:"flex", alignItems:"center", gap:7, flexWrap:"wrap", marginBottom:2 }}>
                          <p style={{ fontWeight:600, margin:0, color:"#1a202c", fontSize:14 }}>{s.name}</p>
                          {savedBatch && (
                            <span style={{ padding:"1px 8px", borderRadius:99, fontSize:11, fontWeight:700, background: batchColor + "22", color: batchColor, border:`1px solid ${batchColor}55` }}>
                              {savedBatch}
                            </span>
                          )}
                        </div>
                        <p style={{ fontSize:12, color:"#718096", margin:"0 0 4px 0" }}>{s.email}</p>
                        {otherCourses.length > 0 && <p style={{ fontSize:11, color:"#764ba2", margin:0 }}>Also enrolled in: {otherCourses.map(e=>e.courseName).join(", ")}</p>}
                      </div>
                      <div style={{ display:"flex", gap:6, flexShrink:0, alignItems:"center" }}>
                        <button title="Assign batch" onClick={()=>setBatchDraft(p=>({ ...p, [s.id]: savedBatch }))} style={{ padding:"5px 9px", background:"rgba(139,92,246,.1)", color:"#8B5CF6", border:"1px solid rgba(139,92,246,.3)", borderRadius:4, cursor:"pointer", fontSize:11, fontWeight:700 }}>🏷️ Batch</button>
                        <button title="Enroll in another course" onClick={()=>{setAddCourseStudentId(s.id);setAddCourseId("");}} style={{ padding:"5px 9px", background:"#eff6ff", color:"#3b82f6", border:"1px solid #bfdbfe", borderRadius:4, cursor:"pointer", fontSize:11, fontWeight:600 }}>+ Course</button>
                        <button onClick={()=>handleRevoke(s.id)} style={{ padding:"5px 9px", background:"#fef2f2", color:"#dc2626", border:"1px solid #fecaca", borderRadius:4, cursor:"pointer", fontSize:11, fontWeight:600 }}>Revoke</button>
                      </div>
                    </div>

                    {/* ── Batch assignment inline panel ── */}
                    {isBatchEditing && (
                      <div style={{ marginTop:10, padding:"10px 12px", background:"rgba(139,92,246,.06)", border:"1px solid rgba(139,92,246,.2)", borderRadius:8 }}>
                        <div style={{ fontSize:11.5, fontWeight:700, color:"#8B5CF6", marginBottom:7 }}>🏷️ Assign Batch for this course</div>
                        <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:8 }}>
                          {BATCH_OPTIONS.map(opt => (
                            <button key={opt} onClick={()=>setBatchDraft(p=>({ ...p, [s.id]: opt === "—" ? "" : opt }))}
                              style={{ padding:"4px 10px", borderRadius:99, fontSize:11, fontWeight:700, cursor:"pointer", border:`1.5px solid ${(draftVal||"")===opt||(opt==="—"&&!draftVal)?"#8B5CF6":"#e2e8f0"}`, background:(draftVal||"")===opt||(opt==="—"&&!draftVal)?"rgba(139,92,246,.15)":"#fff", color:(draftVal||"")===opt||(opt==="—"&&!draftVal)?"#8B5CF6":"#475569" }}>
                              {opt}
                            </button>
                          ))}
                        </div>
                        <div style={{ display:"flex", gap:6 }}>
                          <input value={draftVal} onChange={e=>setBatchDraft(p=>({ ...p, [s.id]: e.target.value }))}
                            placeholder="Or type custom batch name…"
                            style={{ flex:1, padding:"6px 10px", border:"1px solid #cbd5e1", borderRadius:6, fontSize:12, fontFamily:"inherit", outline:"none" }} />
                          <button onClick={()=>handleSetBatch(s.id)} disabled={batchSaving[s.id]}
                            style={{ padding:"6px 14px", background:"#8B5CF6", color:"#fff", border:"none", borderRadius:6, cursor:batchSaving[s.id]?"wait":"pointer", fontSize:12, fontWeight:700, fontFamily:"inherit" }}>
                            {batchSaving[s.id] ? "…" : "Save"}
                          </button>
                          <button onClick={()=>setBatchDraft(p=>{ const n={...p}; delete n[s.id]; return n; })}
                            style={{ padding:"6px 10px", background:"#f1f5f9", color:"#64748b", border:"1px solid #e2e8f0", borderRadius:6, cursor:"pointer", fontSize:12, fontFamily:"inherit" }}>
                            Cancel
                          </button>
                        </div>
                      </div>
                    )}

                    {addCourseStudentId === s.id && (
                      <div style={{ marginTop:10, display:"flex", gap:8 }}>
                        <select value={addCourseId} onChange={e=>setAddCourseId(e.target.value)} style={{ flex:1, padding:"6px 8px", border:"1px solid #cbd5e1", borderRadius:6, fontSize:12, background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)" }}>
                          <option value="">— Select course —</option>
                          {allCourses.filter(c=>!s.enrolledCourseIds?.some(e=>e.courseId===c.id)).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}
                        </select>
                        <button onClick={handleAddCourseEnrollment} style={{ padding:"6px 12px", background:"#3b82f6", color:"white", border:"none", borderRadius:4, cursor:"pointer", fontSize:12, fontWeight:600 }}>Enroll</button>
                        <button onClick={()=>setAddCourseStudentId(null)} style={{ padding:"6px 12px", background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", color:"#64748B", border:"1px solid #fff", borderRadius:99, cursor:"pointer", fontSize:12, boxShadow:"4px 4px 10px #C4CDD9,-3px -3px 8px #fff" }}>✕</button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </>
        )}
        <button onClick={onClose} style={{ width:"100%", marginTop:8, padding:12, background:"#667eea", color:"white", border:"none", borderRadius:8, fontWeight:600, cursor:"pointer" }}>Close</button>
      </div>
    </div>
  );
}



/* ═══════════════════════════════════════════════════════════════════
   TRAINER STUDENT PERFORMANCE PAGE
   Lists all enrolled students; clicking a name loads and shows their
   full StudentDashboard (read-only) with data from Supabase.
═══════════════════════════════════════════════════════════════════ */
function TrainerStudentPerformance({ sb, courseId, planDays, dayMap = {}, darkMode = false }) {
  const [students,    setStudents]    = useState([]);
  const [activityMap, setActivityMap] = useState({});   // { studentId: activityObj }
  const [statusMap,   setStatusMap]   = useState({});   // { studentId: { dayKey: status } }
  const [loading,     setLoading]     = useState(true);
  const [selected,    setSelected]    = useState(null); // studentId currently viewed
  const [loadingId,   setLoadingId]   = useState(null); // studentId being fetched

  /* ── Load all enrolled students + their activity on mount ── */
  useEffect(() => {
    if (!sb || !courseId) { setLoading(false); return; }
    const load = async () => {
      try {
        const { enrolled } = await sbGetLeaderboardData(sb, courseId, planDays);
        setStudents(enrolled);

        // Load both activity cache AND dedicated quiz attempts (source of truth)
        const [aMap, allQuizAttempts] = await Promise.all([
          sbLoadAllStudentActivity(sb, courseId),
          sbLoadAllQuizAttempts(sb, courseId),
        ]);
        // Merge quiz attempts (dedicated table) over activity cache (may be stale)
        const mergedAMap = { ...aMap };
        for (const [sid, quizScores] of Object.entries(allQuizAttempts)) {
          mergedAMap[sid] = {
            ...(mergedAMap[sid] || {}),
            quizScores: { ...(mergedAMap[sid]?.quizScores || {}), ...quizScores },
          };
        }
        setActivityMap(mergedAMap);

        // Load day statuses for all students in parallel
        const sMap = {};
        await Promise.allSettled(enrolled.map(async s => {
          sMap[s.id] = await sbLoadStudentDayStatus(sb, s.id, courseId).catch(() => ({}));
        }));
        setStatusMap(sMap);
      } catch (e) {
        console.error("TrainerStudentPerformance load error:", e.message);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [sb, courseId]);

  /* ── When trainer clicks a student name — ensure their data is loaded ── */
  const handleSelect = async (studentId) => {
    if (selected === studentId) { setSelected(null); return; }
    // If activity/status already loaded, just open
    if (activityMap[studentId] !== undefined && statusMap[studentId] !== undefined) {
      setSelected(studentId);
      return;
    }
    // Otherwise fetch on demand (edge case: new student joined after mount)
    setLoadingId(studentId);
    try {
      const [act, st] = await Promise.all([
        sbLoadMyActivity(sb, studentId, courseId).catch(() => ({})),
        sbLoadStudentDayStatus(sb, studentId, courseId).catch(() => ({})),
      ]);
      setActivityMap(prev => ({ ...prev, [studentId]: act }));
      setStatusMap(prev => ({ ...prev, [studentId]: st }));
    } finally {
      setLoadingId(null);
      setSelected(studentId);
    }
  };

  /* ── Quick summary row stats ── */
  const summaryFor = (s) => {
    const act  = activityMap[s.id] || {};
    const ds   = statusMap[s.id]   || {};
    const total     = planDays.length;
    const completed = Object.values(ds).filter(v => v === "Completed").length;
    const inProg    = Object.values(ds).filter(v => v === "In Progress").length;
    const pct       = total ? Math.round((completed / total) * 100) : 0;
    const quizVals  = Object.values(act.quizScores || {});
    const avgQuiz   = quizVals.length
      ? Math.round(quizVals.reduce((a, q) => a + (q.pct || 0), 0) / quizVals.length)
      : null;
    const codeRuns  = Object.values(act.codeRuns || {}).reduce((a, v) => a + v, 0);
    const lastSeen  = act.lastSeen ? new Date(act.lastSeen).toLocaleDateString() : "—";
    return { total, completed, inProg, pct, avgQuiz, quizCount: quizVals.length, codeRuns, lastSeen };
  };

  const initials = (name) => name ? name.split(" ").map(w => w[0]).join("").slice(0,2).toUpperCase() : "?";
  const avatarColors = ["#3b82f6","#8b5cf6","#10b981","#f59e0b","#ec4899","#06b6d4","#f97316","#6366f1"];
  const avatarColor  = (id) => avatarColors[id.charCodeAt(0) % avatarColors.length];

  if (loading) {
    return (
      <div style={{ display:"flex", alignItems:"center", justifyContent:"center", height:200, color:"#94a3b8", fontSize:14 }}>
        Loading student data…
      </div>
    );
  }

  if (students.length === 0) {
    return (
      <div style={{ maxWidth:600, margin:"60px auto", textAlign:"center" }}>
        <div style={{ fontSize:48, marginBottom:16 }}>👥</div>
        <div style={{ fontSize:18, fontWeight:700, color:"#0f172a", marginBottom:8 }}>No enrolled students yet</div>
        <div style={{ fontSize:13, color:"#94a3b8" }}>Approve students from the Students panel in the sidebar.</div>
      </div>
    );
  }

  const selectedStudent = selected ? students.find(s => s.id === selected) : null;

  return (
    <div style={{ width:"100%", display:"flex", flexDirection:"column", gap:20 }}>

      {/* ── Page header ── */}
      <div style={{ background:"linear-gradient(135deg,#0f172a,#1e3a5f)", borderRadius:14, padding:"20px 24px", color:"#fff" }}>
        <div style={{ fontSize:22, fontWeight:800, marginBottom:4 }}>👥 Student Performance</div>
        <div style={{ fontSize:13, opacity:.7 }}>{students.length} enrolled student{students.length !== 1 ? "s" : ""} · {planDays.length} day course · Click any student to view their full dashboard</div>
      </div>

      {/* ── Student list ── */}
      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {students.map(s => {
          const sum      = summaryFor(s);
          const isOpen   = selected === s.id;
          const isLoading = loadingId === s.id;
          const pctColor = sum.pct >= 75 ? "#16a34a" : sum.pct >= 40 ? "#d97706" : "#dc2626";

          return (
            <div key={s.id} style={{ background: darkMode ? "linear-gradient(145deg,#1e293b,#162032)" : "linear-gradient(145deg,#EDF1F7,#E4E9F2)", borderRadius:20, border:`1.5px solid ${isOpen?"rgba(139,92,246,.5)":(darkMode?"#2a3a52":"#fff")}`, boxShadow: isOpen ? (darkMode?"0 0 0 2px rgba(139,92,246,.18)":"20px 20px 48px #C4CDD9,-12px -12px 32px #fff,0 0 0 2px rgba(139,92,246,.1)") : (darkMode?"none":"12px 12px 28px #C4CDD9,-8px -8px 20px #fff"), transition:"border-color .15s, box-shadow .15s", overflow:"hidden" }}>

              {/* ── Clickable summary row ── */}
              <div
                onClick={() => handleSelect(s.id)}
                style={{ display:"flex", alignItems:"center", gap:14, padding:"14px 18px", cursor:"pointer" }}
                onMouseEnter={e => { if (!isOpen) e.currentTarget.style.background = darkMode ? "#243249" : "#f8fafc"; }}
                onMouseLeave={e => { e.currentTarget.style.background = "transparent"; }}
              >
                {/* Avatar */}
                <div style={{ width:40, height:40, borderRadius:"50%", background:avatarColor(s.id), display:"flex", alignItems:"center", justifyContent:"center", color:"#fff", fontWeight:800, fontSize:14, flexShrink:0 }}>
                  {initials(s.name)}
                </div>

                {/* Name + email */}
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontWeight:700, fontSize:14, color: darkMode ? "#f1f5f9" : "#0f172a", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{s.name}</div>
                  <div style={{ fontSize:11.5, color:"#94a3b8", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{s.email}</div>
                </div>

                {/* Quick stats — hidden on very small screens via minWidth trick */}
                <div style={{ display:"flex", gap:16, alignItems:"center", flexShrink:0 }}>
                  {/* Progress */}
                  <div style={{ textAlign:"center", minWidth:60 }}>
                    <div style={{ fontSize:18, fontWeight:800, color:pctColor, lineHeight:1 }}>{sum.pct}%</div>
                    <div style={{ fontSize:10.5, color:"#94a3b8", marginTop:2 }}>{sum.completed}/{sum.total} days</div>
                  </div>
                  {/* Quiz */}
                  <div style={{ textAlign:"center", minWidth:52 }}>
                    <div style={{ fontSize:18, fontWeight:800, color:"#6366f1", lineHeight:1 }}>{sum.avgQuiz !== null ? `${sum.avgQuiz}%` : "—"}</div>
                    <div style={{ fontSize:10.5, color:"#94a3b8", marginTop:2 }}>{sum.quizCount} quiz{sum.quizCount !== 1 ? "zes" : ""}</div>
                  </div>
                  {/* Code runs */}
                  <div style={{ textAlign:"center", minWidth:44 }}>
                    <div style={{ fontSize:18, fontWeight:800, color:"#3b82f6", lineHeight:1 }}>{sum.codeRuns}</div>
                    <div style={{ fontSize:10.5, color:"#94a3b8", marginTop:2 }}>code runs</div>
                  </div>
                  {/* Last seen */}
                  <div style={{ textAlign:"right", minWidth:72 }}>
                    <div style={{ fontSize:11, color: darkMode ? "#94a3b8" : "#64748b" }}>Last active</div>
                    <div style={{ fontSize:11.5, fontWeight:600, color: darkMode ? "#e2e8f0" : "#334155" }}>{sum.lastSeen}</div>
                  </div>
                  {/* Chevron */}
                  <div style={{ color:"#94a3b8", fontSize:18, transition:"transform .2s", transform: isOpen ? "rotate(180deg)" : "rotate(0deg)" }}>
                    {isLoading ? "⟳" : "⌄"}
                  </div>
                </div>
              </div>

              {/* ── Progress bar strip ── */}
              <div style={{ height:4, background: darkMode ? "#0f172a" : "linear-gradient(145deg,#E4E9F2,#EDF1F7)", boxShadow: darkMode ? "none" : "inset 2px 2px 5px #C4CDD9", marginTop:-2 }}>
                <div style={{ height:"100%", width:`${sum.pct}%`, background:`linear-gradient(90deg,${pctColor},${pctColor}88)`, transition:"width .5s" }} />
              </div>

              {/* ── Expanded student dashboard ── */}
              {isOpen && selectedStudent && (
                <div style={{ borderTop: darkMode ? "1px solid #2a3a52" : "1px solid #e8edf3", padding:"20px 18px", background: darkMode ? "#0f172a" : "#fafbfc" }}>
                  <StudentDashboard
                    planDays={planDays}
                    dayMap={dayMap}
                    dayStatus={statusMap[s.id] || {}}
                    trainerDayStatus={{}}
                    studentActivity={activityMap[s.id] || {}}
                    dayData={{}}
                    startDate={""}
                    courseId={courseId}
                    onSelectDay={() => {}}
                    readOnly={true}
                  />
                </div>
              )}
            </div>
          );
        })}
      </div>

    </div>
  );
}

/* ─── StudentsNavBtn (top-level to avoid remount on each render) ─── */
function StudentsNavBtn({ sb, courseId, trainerId, studentsOpen, setStudentsOpen, collapsed }) {
  const [pendingCount, setPendingCount] = useState(0);

  useEffect(() => {
    if (!sb || !courseId) return;

    const fetchCount = () => {
      // Use the shared helper that queries trainer_id + JSONB pending_course_ids
      // + JSONB enrolled_course_ids + legacy requested_course_id in parallel.
      // This guarantees cross-trainer requests are never missed.
      sbGetStudentsForCourse(sb, courseId, trainerId)
        .then(students => {
          const count = students.filter(s => {
            const inPending    = Array.isArray(s.pendingCourseIds) && s.pendingCourseIds.some(p => p.courseId === courseId);
            const legacyPending = !s.approved && s.requestedCourseId === courseId;
            return inPending || legacyPending;
          }).length;
          setPendingCount(count);
        })
        .catch(() => {});
    };

    fetchCount();
    const interval = setInterval(fetchCount, 8000); // poll every 8 s
    return () => clearInterval(interval);
  }, [studentsOpen, sb, courseId, trainerId]);

  return (
    <button className={`lms-nav${studentsOpen?" on":""}`} onClick={()=>setStudentsOpen(p=>!p)} title={collapsed?"Students":""} style={{ position:"relative" }}>
      <Ic n="teacher" s={16} />
      {!collapsed && <span>Students</span>}
      {pendingCount > 0 && (
        <span style={{ marginLeft:"auto", background:"#f59e0b", color:"#fff", borderRadius:99, fontSize:9, fontWeight:800, padding:"2px 6px", lineHeight:1.4, flexShrink:0 }}>
          {pendingCount}
        </span>
      )}
    </button>
  );
}

/* ─── StudentsPanel (top-level to avoid remount on each render) ─── */
function StudentsPanel({ sb, courseId, trainerId, collapsed, setStudentsOpen, darkMode = false }) {
  const [list, setList] = useState([]);

  // FIX: dual-query strategy so requests are never missed:
  //   1. By trainer_id  — students whose primary trainer is this trainer
  //   2. By requested_course_id — catches students who selected this course but
  //      whose trainer_id points to a different trainer (multi-trainer enrollment)
  // Results are merged + deduplicated, then filtered to this course only.
  // Also polls every 8 s so new requests appear without a manual panel close/open.
  const fetchList = useCallback(() => {
    if (!sb || !courseId) return;
    // sbGetStudentsForCourse queries ALL 4 paths in parallel (trainer_id,
    // pending JSONB, enrolled JSONB, legacy requested_course_id) so
    // cross-trainer requests are never missed.
    sbGetStudentsForCourse(sb, courseId, trainerId)
      .then(students => {
        setList(students.filter(s => {
          const inPending      = Array.isArray(s.pendingCourseIds)  && s.pendingCourseIds.some(p => p.courseId === courseId);
          const legacyPending  = !s.approved && s.requestedCourseId === courseId && !Array.isArray(s.pendingCourseIds);
          const inEnrolled     = Array.isArray(s.enrolledCourseIds) && s.enrolledCourseIds.some(e => e.courseId === courseId);
          const legacyApproved = s.approved && s.requestedCourseId === courseId && !Array.isArray(s.enrolledCourseIds);
          return inPending || legacyPending || inEnrolled || legacyApproved;
        }));
      })
      .catch(() => {});
  }, [sb, courseId, trainerId]);

  useEffect(() => {
    fetchList(); // load immediately on open
    const interval = setInterval(fetchList, 8000); // auto-refresh every 8 s
    return () => clearInterval(interval);
  }, [fetchList]);

  const approved = list.filter(s => Array.isArray(s.enrolledCourseIds) ? s.enrolledCourseIds.some(e => e.courseId === courseId) : (s.approved && s.requestedCourseId === courseId));
  const pending  = list.filter(s => Array.isArray(s.pendingCourseIds) ? s.pendingCourseIds.some(p => p.courseId === courseId) : (!s.approved && s.requestedCourseId === courseId));

  const handleApprove = async (id) => {
    const s = list.find(x => x.id === id); if (!s) return;
    const pendingEntry = Array.isArray(s.pendingCourseIds) ? s.pendingCourseIds.find(p => p.courseId === courseId) : null;
    const resolvedCourseName = pendingEntry?.courseName || s.requestedCourseName || courseId;
    const newEnrolled = [...(s.enrolledCourseIds||[])];
    if (!newEnrolled.some(e => e.courseId === courseId)) newEnrolled.push({ courseId, courseName: resolvedCourseName, approvedAt: new Date().toISOString() });
    const newPending = Array.isArray(s.pendingCourseIds) ? s.pendingCourseIds.filter(p => p.courseId !== courseId) : [];
    const updated = { ...s, enrolledCourseIds: newEnrolled, pendingCourseIds: newPending, approved: true, approvedAt: new Date().toISOString() };
    sbCreateNotification(sb, {
      studentId: s.id,
      courseId,
      type: "enrollment_approved",
      title: `You're in: ${resolvedCourseName || "your course"}`,
      body: "Your enrolment was approved. Open the course to start.",
    }).catch(() => {});
    await sbSaveStudent(sb, updated).catch(() => {});
    setList(prev => prev.map(x => x.id === id ? updated : x));
  };
  const handleReject = async (id) => {
    const s = list.find(x => x.id === id);
    if (!s) return;
    // Strip only this course from both arrays — never blindly delete the whole record.
    // A student enrolled/pending across multiple trainers must stay in the DB for the others.
    const newPending  = Array.isArray(s.pendingCourseIds)  ? s.pendingCourseIds.filter(p  => p.courseId  !== courseId) : [];
    const newEnrolled = Array.isArray(s.enrolledCourseIds) ? s.enrolledCourseIds.filter(e => e.courseId  !== courseId) : [];
    const hasOtherPending    = newPending.length > 0;
    const hasOtherEnrolled   = newEnrolled.length > 0;
    // Student is approved for a different course via the legacy single-course field
    const hasLegacyElsewhere = s.approved && s.requestedCourseId && s.requestedCourseId !== courseId;
    // After ALTER TABLE every student has JSONB arrays, so !Array.isArray is always false —
    // drop that guard and use a clean check: delete only when truly nothing remains anywhere.
    if (!hasOtherPending && !hasOtherEnrolled && !hasLegacyElsewhere) {
      await sbDeleteStudent(sb, id).catch(() => {});
    } else {
      await sbSaveStudent(sb, { ...s, pendingCourseIds: newPending, enrolledCourseIds: newEnrolled }).catch(() => {});
    }
    setList(prev => prev.filter(x => x.id !== id));
  };

  return (
    <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, zIndex:500, display:"flex" }} onClick={e=>{ if(e.target===e.currentTarget) setStudentsOpen(false); }}>
      <div style={{ width: collapsed ? 58 : 210, flexShrink:0 }} />
      <div style={{ width:300, background: darkMode ? "#111827" : "linear-gradient(180deg,#EDF1F7 0%,#E4E9F2 100%)", borderRight: darkMode ? "1.5px solid #1f2937" : "1.5px solid #C4CDD9", display:"flex", flexDirection:"column", boxShadow:"8px 0 24px rgba(196,205,217,.4)", animation:"lms-slide .2s ease", height:"100vh", overflow:"hidden" }}>
        <div style={{ padding:"16px 16px 12px", borderBottom: darkMode ? "1px solid #1f2937" : "1px solid #f1f5f9", display:"flex", alignItems:"center", justifyContent:"space-between", flexShrink:0 }}>
          <div>
            <p style={{ fontWeight:700, fontSize:14, color: darkMode ? "#f1f5f9" : "#0f172a", margin:0 }}>Students</p>
            <p style={{ fontSize:11.5, color:"#94a3b8", margin:"2px 0 0 0" }}>{list.length} enrolled · {pending.length} pending</p>
          </div>
          <button onClick={()=>setStudentsOpen(false)} style={{ background: darkMode ? "linear-gradient(145deg,#1e293b,#162032)" : "linear-gradient(145deg,#EDF1F7,#E4E9F2)", border: darkMode ? "1px solid #2a3a52" : "1px solid #fff", borderRadius:10, cursor:"pointer", padding:"5px 8px", color: darkMode ? "#cbd5e1" : "#64748B", display:"flex", alignItems:"center", boxShadow: darkMode ? "none" : "4px 4px 10px #C4CDD9,-3px -3px 8px #fff" }}><Ic n="x" s={14}/></button>
        </div>
        <div style={{ flex:1, overflowY:"auto", padding:"12px 10px" }}>
          {pending.length > 0 && (
            <div style={{ marginBottom:16 }}>
              <div style={{ fontSize:10, fontWeight:700, color:"#f59e0b", textTransform:"uppercase", letterSpacing:".07em", padding:"0 6px 8px" }}>⏳ Pending ({pending.length})</div>
              {pending.map(s => (
                <div key={s.id} style={{ background: darkMode ? "rgba(120,53,15,.25)" : "#fffbeb", border: darkMode ? "1px solid rgba(253,230,138,.35)" : "1px solid #fde68a", borderRadius:10, padding:"10px 12px", marginBottom:8 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:9, marginBottom:8 }}>
                    <div style={{ width:30, height:30, borderRadius:"50%", background: darkMode ? "rgba(217,119,6,.3)" : "#fef3c7", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:700, color: darkMode ? "#fbbf24" : "#92400e", flexShrink:0 }}>{s.name.charAt(0).toUpperCase()}</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontSize:12.5, fontWeight:700, color: darkMode ? "#f1f5f9" : "#0f172a", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{s.name}</div>
                      <div style={{ fontSize:11, color: darkMode ? "#a8a29e" : "#78716c", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{s.email}</div>
                    </div>
                  </div>
                  <div style={{ display:"flex", gap:6 }}>
                    <button onClick={()=>handleApprove(s.id)} style={{ flex:1, padding:"5px 0", background:"#22c55e", color:"#fff", border:"none", borderRadius:6, fontSize:11.5, fontWeight:700, cursor:"pointer" }}>✓ Approve</button>
                    <button onClick={()=>handleReject(s.id)} style={{ flex:1, padding:"5px 0", background: darkMode ? "rgba(127,29,29,.35)" : "#fee2e2", color: darkMode ? "#fca5a5" : "#dc2626", border:"none", borderRadius:6, fontSize:11.5, fontWeight:700, cursor:"pointer" }}>✕ Reject</button>
                  </div>
                </div>
              ))}
            </div>
          )}
          {approved.length > 0 && (
            <div>
              <div style={{ fontSize:10, fontWeight:700, color:"#22c55e", textTransform:"uppercase", letterSpacing:".07em", padding:"0 6px 8px" }}>✓ Enrolled ({approved.length})</div>
              {approved.map(s => (
                <div key={s.id} style={{ background: darkMode ? "rgba(20,83,45,.25)" : "#f0fdf4", border: darkMode ? "1px solid rgba(134,239,172,.3)" : "1px solid #bbf7d0", borderRadius:10, padding:"10px 12px", marginBottom:8 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:9, marginBottom:8 }}>
                    <div style={{ width:30, height:30, borderRadius:"50%", background: darkMode ? "rgba(34,197,94,.25)" : "#dcfce7", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:700, color: darkMode ? "#86efac" : "#15803d", flexShrink:0 }}>{s.name.charAt(0).toUpperCase()}</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontSize:12.5, fontWeight:700, color: darkMode ? "#f1f5f9" : "#0f172a", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{s.name}</div>
                      <div style={{ fontSize:11, color: darkMode ? "#94a3b8" : "#64748b", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{s.email}</div>
                    </div>
                  </div>
                  <button onClick={()=>handleReject(s.id)} style={{ width:"100%", padding:"5px 0", background: darkMode ? "rgba(127,29,29,.35)" : "#fee2e2", color: darkMode ? "#fca5a5" : "#dc2626", border:"none", borderRadius:6, fontSize:11.5, fontWeight:700, cursor:"pointer" }}>Remove</button>
                </div>
              ))}
            </div>
          )}
          {list.length === 0 && <div style={{ textAlign:"center", padding:"40px 16px", color:"#94a3b8", fontSize:13 }}>No students yet</div>}
        </div>
      </div>
    </div>
  );
}

/* ─── StudentCourseView (top-level to avoid remount on each render) ─── */
/* ═══════════════════════════════════════════════════════════════════
   NOTIFICATION BELL (student)
   Polls on mount, on window focus and every 25s. Anything unseen also
   fires a system notification so it lands even when the tab is in the
   background on a phone or a laptop.
═══════════════════════════════════════════════════════════════════ */
const NOTIF_SEEN_LS = "lms_notif_seen_v1";

function notifSeenIds() {
  try { return new Set(JSON.parse(localStorage.getItem(NOTIF_SEEN_LS) || "[]")); } catch { return new Set(); }
}
function notifRememberIds(ids) {
  try {
    const merged = Array.from(new Set([...notifSeenIds(), ...ids])).slice(-300);
    localStorage.setItem(NOTIF_SEEN_LS, JSON.stringify(merged));
  } catch {}
}

function StudentNotifications({ sb, studentId, onCourseApproved }) {
  const [items, setItems]   = useState([]);
  const [open, setOpen]     = useState(false);
  const [perm, setPerm]     = useState(() => (typeof Notification !== "undefined" ? Notification.permission : "unsupported"));
  const firstLoad           = useRef(true);

  const unread = items.filter(n => !n.read).length;

  const fire = useCallback((n) => {
    if (typeof Notification === "undefined" || Notification.permission !== "granted") return;
    try {
      const sysNote = new Notification(n.title, { body: n.body || "", tag: n.id, icon: "/favicon.ico" });
      sysNote.onclick = () => { window.focus(); setOpen(true); sysNote.close(); };
    } catch {}
  }, []);

  const load = useCallback(async () => {
    if (!sb || !studentId) return;
    const rows = await sbGetNotifications(sb, studentId);
    setItems(rows);
    // On the very first poll we only record what exists — we don't replay
    // a week of history as system toasts.
    const seen = notifSeenIds();
    const fresh = rows.filter(n => !seen.has(n.id));
    if (!firstLoad.current) {
      fresh.forEach(n => {
        fire(n);
        if (n.type === "enrollment_approved" && onCourseApproved) onCourseApproved(n);
      });
    }
    if (fresh.length) notifRememberIds(fresh.map(n => n.id));
    firstLoad.current = false;
  }, [sb, studentId, fire, onCourseApproved]);

  useEffect(() => {
    load();
    const iv = setInterval(load, 25000);
    const onFocus = () => load();
    window.addEventListener("focus", onFocus);
    return () => { clearInterval(iv); window.removeEventListener("focus", onFocus); };
  }, [load]);

  const askPermission = async () => {
    if (typeof Notification === "undefined") return;
    try { const p = await Notification.requestPermission(); setPerm(p); } catch {}
  };

  const markAllRead = async () => {
    const ids = items.filter(n => !n.read).map(n => n.id);
    if (!ids.length) return;
    setItems(prev => prev.map(n => ({ ...n, read: true })));
    await sbMarkNotificationsRead(sb, ids).catch(() => {});
  };

  const when = (iso) => {
    const diff = Date.now() - new Date(iso).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return "just now";
    if (mins < 60) return `${mins}m ago`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return `${hrs}h ago`;
    return `${Math.floor(hrs / 24)}d ago`;
  };

  return (
    <div style={{ position:"relative" }}>
      <button
        onClick={() => { setOpen(o => !o); if (!open) markAllRead(); }}
        aria-label={unread ? `${unread} unread notifications` : "Notifications"}
        style={{
          position:"relative", width:38, height:38, borderRadius:12, cursor:"pointer",
          background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", border:"1.5px solid #C4CDD9",
          display:"flex", alignItems:"center", justifyContent:"center", fontSize:17,
        }}>
        🔔
        {unread > 0 && (
          <span style={{
            position:"absolute", top:-4, right:-4, minWidth:18, height:18, padding:"0 5px",
            borderRadius:99, background:"#ef4444", color:"#fff", fontSize:11, fontWeight:800,
            display:"flex", alignItems:"center", justifyContent:"center",
            boxShadow:"0 2px 6px rgba(239,68,68,.5)",
          }}>{unread > 9 ? "9+" : unread}</span>
        )}
      </button>

      {open && (
        <>
          <div onClick={() => setOpen(false)} style={{ position:"fixed", inset:0, zIndex:190 }}/>
          <div style={{
            position:"absolute", right:0, top:46, width:326, maxWidth:"calc(100vw - 32px)", zIndex:200,
            background:"#fff", borderRadius:16, border:"1.5px solid #e2e8f0",
            boxShadow:"0 18px 44px rgba(15,23,42,.18)", overflow:"hidden",
          }}>
            <div style={{ padding:"13px 16px", borderBottom:"1px solid #f1f5f9", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
              <p style={{ fontWeight:800, fontSize:14, color:"#0f172a" }}>Notifications</p>
              {items.length > 0 && <span style={{ fontSize:11.5, color:"#94a3b8" }}>{items.length}</span>}
            </div>

            {perm === "default" && (
              <div style={{ padding:"11px 16px", background:"#faf8ff", borderBottom:"1px solid #f1f5f9" }}>
                <p style={{ fontSize:12.5, color:"#5b21b6", marginBottom:8, lineHeight:1.5 }}>
                  Turn on alerts to hear about approvals while you're on another tab.
                </p>
                <button onClick={askPermission} style={{ padding:"6px 13px", borderRadius:8, border:"none", background:"#7c3aed", color:"#fff", fontSize:12, fontWeight:700, cursor:"pointer" }}>
                  Turn on alerts
                </button>
              </div>
            )}

            <div style={{ maxHeight:330, overflowY:"auto" }}>
              {items.length === 0 ? (
                <p style={{ padding:"26px 16px", textAlign:"center", color:"#94a3b8", fontSize:13 }}>
                  Nothing yet. Approvals and course updates land here.
                </p>
              ) : items.map(n => (
                <div key={n.id} style={{
                  padding:"12px 16px", borderBottom:"1px solid #f8fafc",
                  background: n.read ? "#fff" : "#faf8ff",
                  display:"flex", gap:10, alignItems:"flex-start",
                }}>
                  <span style={{ fontSize:16, lineHeight:1.3, flexShrink:0 }}>
                    {n.type === "enrollment_approved" ? "✅" : n.type === "enrollment_rejected" ? "⚠️" : "📢"}
                  </span>
                  <div style={{ minWidth:0 }}>
                    <p style={{ fontSize:13.2, fontWeight:700, color:"#0f172a", lineHeight:1.4 }}>{n.title}</p>
                    {n.body && <p style={{ fontSize:12.3, color:"#64748b", marginTop:3, lineHeight:1.5 }}>{n.body}</p>}
                    <p style={{ fontSize:11, color:"#a8b3c4", marginTop:4 }}>{when(n.created_at)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

function StudentCourseView({ sb, auth, handleLogout }) {
  // FIX 11 & 12: Added refresh mechanism + retry on empty enrollment
  const [enrolledCourses, setEnrolledCourses] = useState([]);
  const [pendingCourses, setPendingCourses]   = useState([]);
  const [activeCourseId, setActiveCourseId]   = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshKey, setRefreshKey] = useState(0);

  // Post-login enrollment request state
  const [showEnrollPanel, setShowEnrollPanel]   = useState(false);
  const [allCourses, setAllCourses]             = useState([]);
  const [trainersMap, setTrainersMap]           = useState({});
  const [selectedEnrollIds, setSelectedEnrollIds] = useState([]);
  const [enrolling, setEnrolling]               = useState(false);
  const [enrollMsg, setEnrollMsg]               = useState("");

  const loadStudent = () => {
    if (!sb) return;
    setLoading(true);
    Promise.all([
      sb.select("lms_students", `id=eq.${encodeURIComponent(auth.id)}&limit=1`),
      sbGetTrainers(sb).catch(() => []),
      sbGetCourses(sb).catch(() => []),
    ]).then(([rows, trainerRows, courseRows]) => {
      const student = rows?.[0] ? dbRowToStudent(rows[0]) : null;
      if (!student) { setLoading(false); return; }
      const tMap = {};
      (trainerRows || []).forEach(t => { tMap[t.id] = t; });
      setTrainersMap(tMap);
      const cMap = {};
      (courseRows || []).map(dbRowToCourse).forEach(c => { cMap[c.id] = c; });
      const enrolled = getStudentEnrolledCourses(student);
      setEnrolledCourses(enrolled);
      // Hide pending requests tied to a trainer who is no longer approved —
      // student keeps seeing only their actually-enrolled course(s) for him.
      // trainerId is read from the pending entry itself, falling back to the
      // course record for older entries saved before trainerId was stored.
      const visiblePending = (student.pendingCourseIds || []).filter(p => {
        const tId = p.trainerId || cMap[p.courseId]?.trainerId;
        return tMap[tId]?.approved === true;
      });
      setPendingCourses(visiblePending);
      // Default to first enrolled course; preserve active selection if still valid
      setActiveCourseId(prev => {
        if (prev && enrolled.some(e => e.courseId === prev)) return prev;
        return enrolled[0]?.courseId || null;
      });
      setLoading(false);
    }).catch(() => setLoading(false));
  };

  // FIX 12: re-runs when refreshKey increments (manual refresh button)
  useEffect(() => { loadStudent(); }, [sb, auth.id, refreshKey]);

  // ENROLLMENT GUARD: poll Supabase every 10 s to detect trainer removal.
  // If the student's active course disappears from their enrolled list, log them
  // out immediately so they can't keep viewing content after being removed.
  useEffect(() => {
    if (!sb || !auth?.id) return;
    const interval = setInterval(async () => {
      try {
        const rows = await sb.select("lms_students", `id=eq.${encodeURIComponent(auth.id)}&limit=1`);
        const student = rows?.[0] ? dbRowToStudent(rows[0]) : null;
        if (!student) {
          // Student record deleted entirely — log out immediately
          handleLogout();
          return;
        }
        const freshEnrolled = getStudentEnrolledCourses(student);
        // If they had at least one course before and now have none, log out
        if (freshEnrolled.length === 0) {
          handleLogout();
          return;
        }
        // If the currently active course was specifically removed, either
        // switch to another enrolled course or log out if none remain
        setActiveCourseId(prev => {
          if (!prev) return freshEnrolled[0]?.courseId || null;
          const stillEnrolled = freshEnrolled.some(e => e.courseId === prev);
          if (!stillEnrolled) {
            // Active course removed — switch to first remaining or log out
            const next = freshEnrolled[0]?.courseId || null;
            if (!next) {
              // Schedule logout outside the state setter
              setTimeout(() => handleLogout(), 0);
            }
            return next;
          }
          return prev;
        });
        // Keep enrolledCourses in sync with the fresh data
        setEnrolledCourses(freshEnrolled);
      } catch {
        // Network blip — skip this poll, try again next interval
      }
    }, 5000);
    return () => clearInterval(interval);
  }, [sb, auth?.id]);

  // Load all available courses whenever enrollment panel opens.
  // Only currently-approved trainers' courses are shown — a revoked
  // trainer's other courses stay hidden from new enrollment requests.
  useEffect(() => {
    if (!showEnrollPanel || !sb) return;
    sbGetTrainers(sb).then(trainers => {
      const m = {};
      trainers.forEach(t => { m[t.id] = t; });
      setTrainersMap(m);
      sbGetCourses(sb).then(rows => {
        const courses = rows.map(dbRowToCourse).filter(c => m[c.trainerId]?.approved === true);
        setAllCourses(courses);
      }).catch(() => {});
    }).catch(() => {});
  }, [showEnrollPanel, sb]);

  const handleRequestEnrollment = async () => {
    if (!selectedEnrollIds.length) { setEnrollMsg("Please select at least one course."); return; }
    setEnrolling(true); setEnrollMsg("");
    try {
      const rows = await sb.select("lms_students", `id=eq.${encodeURIComponent(auth.id)}&limit=1`);
      const student = rows?.[0] ? dbRowToStudent(rows[0]) : null;
      if (!student) throw new Error("Could not load your profile. Please refresh.");
      const existing = [
        ...(student.pendingCourseIds || []).map(p => p.courseId),
        ...(student.enrolledCourseIds || []).map(e => e.courseId),
      ];
      const newRequests = selectedEnrollIds.filter(id => !existing.includes(id));
      if (!newRequests.length) { setEnrollMsg("You are already enrolled or pending in all selected courses."); setEnrolling(false); return; }
      const newPending = [
        ...(student.pendingCourseIds || []),
        ...newRequests.map(cid => {
          const c = allCourses.find(x => x.id === cid);
          // trainerId stored per entry so sbGetStudentsForCourse's JSONB
          // containment query finds this student for the correct trainer.
          return {
            courseId: cid,
            courseName: c?.name || "",
            trainerId: c?.trainerId || "",
            requestedAt: new Date().toISOString(),
          };
        }),
      ];
      await sbSaveStudent(sb, { ...student, pendingCourseIds: newPending });
      setEnrollMsg(`✅ Enrollment request sent for ${newRequests.length} course(s)! Wait for trainer approval.`);
      setSelectedEnrollIds([]);
    } catch(e) { setEnrollMsg("❌ " + e.message); }
    setEnrolling(false);
  };

  const hasAnyCourse = enrolledCourses.length > 0;
  const activeCourseName = enrolledCourses.find(e => e.courseId === activeCourseId)?.courseName || "Your Course";

  // Courses not yet enrolled/pending — for the enroll panel
  const availableToEnroll = allCourses.filter(c => {
    const pendingIds = []; // will check against live student data inside handler
    return !enrolledCourses.some(e => e.courseId === c.id);
  });

  if (loading) return <div style={{ textAlign:"center", padding:"60px 20px", color:"#94a3b8", fontSize:14 }}>Loading…</div>;

  return (
    <div style={{ minHeight:"100vh", background:"#EDF1F7" }}>
      <div style={{ background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", padding:"14px 24px", borderBottom:"1.5px solid #C4CDD9", display:"flex", justifyContent:"space-between", alignItems:"center", position:"sticky", top:0, zIndex:100, boxShadow:"0 4px 16px rgba(196,205,217,.35)", gap:12 }}>
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          <AppLogo
            size="md"
            theme="light"
            onClick={handleLogout}
            subtitle={`👨‍🎓 ${auth.name}${hasAnyCourse ? ` · ${activeCourseName}` : ""}`}
          />
          <span style={{ background:"#f0fdf4", color:"#16a34a", border:"1px solid #bbf7d0", borderRadius:99, fontSize:10, fontWeight:700, padding:"2px 8px", whiteSpace:"nowrap" }}>🔄 Live</span>
        </div>
        <div style={{ display:"flex", gap:8, alignItems:"center" }}>
          <StudentNotifications sb={sb} studentId={auth?.id} onCourseApproved={loadStudent} />
          {enrolledCourses.length > 1 && (
            <select value={activeCourseId||""} onChange={e=>setActiveCourseId(e.target.value)} style={{ padding:"8px 12px", border:"1px solid #fff", borderRadius:99, fontSize:12, fontWeight:700, color:"#8B5CF6", background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", cursor:"pointer", maxWidth:200, boxShadow:"6px 6px 14px #C4CDD9,-4px -4px 10px #fff" }}>
              {enrolledCourses.map(e=><option key={e.courseId} value={e.courseId}>{e.courseName}</option>)}
            </select>
          )}
          {/* Enroll in Another Course */}
          <button
            onClick={()=>{ setShowEnrollPanel(p=>!p); setEnrollMsg(""); setSelectedEnrollIds([]); }}
            style={{ padding:"8px 16px", background:"linear-gradient(135deg,#8B5CF6,#6366F1)", color:"#fff", border:"none", borderRadius:99, cursor:"pointer", fontSize:12, fontWeight:700, boxShadow:"6px 6px 14px #C4CDD9,-3px -3px 10px #fff,0 4px 16px rgba(139,92,246,.3)" }}
            title="Request enrollment in additional courses"
          >
            ➕ More Courses
          </button>
          {/* FIX: always show refresh — lets students re-check enrollment after approval */}
          <button onClick={()=>setRefreshKey(k=>k+1)} style={{ padding:"8px 16px", background:"linear-gradient(135deg,#14B8A6,#5EEAD4)", color:"#fff", border:"none", borderRadius:99, cursor:"pointer", fontSize:12, fontWeight:700, boxShadow:"6px 6px 14px #C4CDD9,-3px -3px 10px #fff,0 4px 16px rgba(20,184,166,.3)" }}>
            🔄 Refresh
          </button>
          <button onClick={handleLogout} style={{ padding:"8px 20px", background:"linear-gradient(135deg,#f43f5e,#e879f9)", color:"white", border:"none", borderRadius:99, cursor:"pointer", fontWeight:700, boxShadow:"6px 6px 14px #C4CDD9,-3px -3px 10px #fff,0 4px 16px rgba(244,63,94,.3)" }}>Logout</button>
        </div>
      </div>

      {/* ── Enroll in Another Course Panel ── */}
      {showEnrollPanel && (
        <div style={{ background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", borderBottom:"1.5px solid #C4CDD9", padding:"20px 24px", boxShadow:"0 6px 24px rgba(196,205,217,.35)" }}>
          <div style={{ maxWidth:720, margin:"0 auto" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:12 }}>
              <div>
                <p style={{ fontWeight:700, fontSize:15, color:"#5b21b6", margin:0 }}>📚 Request Enrollment in More Courses</p>
                <p style={{ fontSize:12, color:"#94a3b8", margin:"2px 0 0 0" }}>Select courses below — your trainer will be notified to approve you.</p>
              </div>
              <button onClick={()=>setShowEnrollPanel(false)} style={{ background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", border:"1px solid #fff", borderRadius:10, cursor:"pointer", padding:"5px 8px", color:"#64748B", boxShadow:"4px 4px 10px #C4CDD9,-3px -3px 8px #fff" }}>✕</button>
            </div>

            {allCourses.length === 0
              ? <p style={{ color:"#94a3b8", fontSize:13 }}>Loading available courses…</p>
              : (()=>{
                  // Group by trainer
                  const byTrainer = {};
                  allCourses.forEach(c => {
                    const tName = trainersMap[c.trainerId]?.name || "Unknown Trainer";
                    if (!byTrainer[tName]) byTrainer[tName] = [];
                    byTrainer[tName].push(c);
                  });
                  return (
                    <div style={{ display:"flex", flexWrap:"wrap", gap:12, marginBottom:14 }}>
                      {Object.entries(byTrainer).map(([tName, courses]) => (
                        <div key={tName} style={{ background:"#faf5ff", border:"1.5px solid #ede9fe", borderRadius:10, padding:"10px 14px", minWidth:200, flex:"1 1 200px" }}>
                          <div style={{ fontSize:11, fontWeight:700, color:"#764ba2", textTransform:"uppercase", letterSpacing:".06em", marginBottom:8 }}>👨‍🏫 {tName}</div>
                          {courses.map(c => {
                            const alreadyEnrolled = enrolledCourses.some(e => e.courseId === c.id);
                            const checked = selectedEnrollIds.includes(c.id);
                            return (
                              <label key={c.id} style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6, cursor:alreadyEnrolled?"default":"pointer", opacity:alreadyEnrolled?.55:1 }}>
                                <input type="checkbox"
                                  checked={checked || alreadyEnrolled}
                                  disabled={alreadyEnrolled}
                                  onChange={e => {
                                    if (e.target.checked) setSelectedEnrollIds(prev => [...prev, c.id]);
                                    else setSelectedEnrollIds(prev => prev.filter(id => id !== c.id));
                                  }}
                                  style={{ width:14, height:14, accentColor:"#764ba2", cursor:alreadyEnrolled?"default":"pointer" }}
                                />
                                <span style={{ fontSize:13, color:alreadyEnrolled?"#94a3b8":checked?"#5b21b6":"#374151", fontWeight:checked?600:400 }}>
                                  {c.name} {alreadyEnrolled && <span style={{ fontSize:10, color:"#22c55e", fontWeight:700 }}>✓ enrolled</span>}
                                </span>
                              </label>
                            );
                          })}
                        </div>
                      ))}
                    </div>
                  );
                })()
            }

            {enrollMsg && (
              <div style={{ padding:"9px 14px", borderRadius:8, marginBottom:10, background:enrollMsg.startsWith("✅")?"#f0fdf4":"#fef2f2", border:`1px solid ${enrollMsg.startsWith("✅")?"#bbf7d0":"#fecaca"}`, fontSize:13, color:enrollMsg.startsWith("✅")?"#15803d":"#dc2626", fontWeight:600 }}>
                {enrollMsg}
              </div>
            )}

            <div style={{ display:"flex", gap:10 }}>
              <button
                onClick={handleRequestEnrollment}
                disabled={enrolling || !selectedEnrollIds.length}
                style={{ padding:"9px 20px", background:"#764ba2", color:"white", border:"none", borderRadius:8, fontWeight:700, cursor:"pointer", fontSize:13, opacity:(enrolling||!selectedEnrollIds.length)?.6:1 }}
              >
                {enrolling ? "Sending…" : `Request Enrollment (${selectedEnrollIds.length} selected)`}
              </button>
              <button onClick={()=>{ setShowEnrollPanel(false); setEnrollMsg(""); setSelectedEnrollIds([]); }} style={{ padding:"9px 18px", background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", color:"#64748B", border:"1px solid #fff", borderRadius:99, fontWeight:700, cursor:"pointer", fontSize:13, boxShadow:"6px 6px 14px #C4CDD9,-4px -4px 10px #fff" }}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {hasAnyCourse && activeCourseId ? (
        <OriginalLMSApp key={activeCourseId} courseId={activeCourseId} studentMode={true} sb={sb} studentId={auth?.id} auth={auth} enrolledCourses={enrolledCourses} pendingCourses={pendingCourses} />
      ) : (
        <div style={{ maxWidth:600, margin:"80px auto", padding:"0 20px", textAlign:"center" }}>
          <div style={{ background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", borderRadius:22, padding:"48px 40px", boxShadow:"20px 20px 48px #C4CDD9,-12px -12px 32px #fff", border:"1px solid #fff" }}>
            <div style={{ fontSize:48, marginBottom:16 }}>⏳</div>
            <h2 style={{ color:"#1a202c", margin:"0 0 10px 0", fontSize:22, fontWeight:700 }}>Awaiting Course Assignment</h2>
            <p style={{ color:"#94a3b8", margin:"0 0 20px 0", lineHeight:1.6 }}>Your account is pending or no course has been assigned yet. Please contact your trainer — then click Refresh above.</p>
            <div style={{ display:"flex", gap:10, justifyContent:"center", flexWrap:"wrap" }}>
              <button onClick={()=>setRefreshKey(k=>k+1)} style={{ padding:"10px 24px", background:"#667eea", color:"white", border:"none", borderRadius:8, fontWeight:600, cursor:"pointer", fontSize:14 }}>
                🔄 Check Again
              </button>
              <button onClick={()=>{ setShowEnrollPanel(true); setEnrollMsg(""); setSelectedEnrollIds([]); }} style={{ padding:"10px 24px", background:"#f5f3ff", color:"#764ba2", border:"1px solid #ddd6fe", borderRadius:8, fontWeight:600, cursor:"pointer", fontSize:14 }}>
                ➕ Request a Course
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   LEADERBOARD PAGE — visible to both trainer and students
   Scores are computed from shared course data (dayStatus, dayData).
   No schema changes needed — all derived from existing Supabase tables.
═══════════════════════════════════════════════════════════════════ */
function LeaderboardPage({ sb, courseId, planDays, studentMode, currentStudentId }) {
  const [students,    setStudents]    = useState([]);
  const [activityMap, setActivityMap] = useState({});   // { studentId: activityObj }
  const [dayStatusMap,setDayStatusMap]= useState({});   // { studentId: { dayKey: status } }
  const [loading,     setLoading]     = useState(true);
  const [error,       setError]       = useState(null);
  const [sortKey,     setSortKey]     = useState("score");
  const [filter,      setFilter]      = useState("");
  const [expanded,    setExpanded]    = useState(null);  // studentId of expanded row

  /* ── Fetch all enrolled students + their activity + their day statuses ── */
  useEffect(() => {
    if (!sb || !courseId) { setLoading(false); return; }
    const load = async () => {
      try {
        // 1. Students enrolled in this course
        const { enrolled } = await sbGetLeaderboardData(sb, courseId, planDays);
        setStudents(enrolled);

        // 2. Activity map + quiz attempts (dedicated table = source of truth)
        const [aMap, allQuizAttempts] = await Promise.all([
          sbLoadAllStudentActivity(sb, courseId),
          sbLoadAllQuizAttempts(sb, courseId),
        ]);
        // Merge quiz attempts over activity cache so scores are never stale
        const mergedAMap = { ...aMap };
        for (const [sid, quizScores] of Object.entries(allQuizAttempts)) {
          mergedAMap[sid] = {
            ...(mergedAMap[sid] || {}),
            quizScores: { ...(mergedAMap[sid]?.quizScores || {}), ...quizScores },
          };
        }
        setActivityMap(mergedAMap);

        // 3. Per-student day status map (parallel fetch)
        const statusMap = {};
        await Promise.allSettled(enrolled.map(async s => {
          const st = await sbLoadStudentDayStatus(sb, s.id, courseId);
          statusMap[s.id] = st || {};
        }));
        setDayStatusMap(statusMap);
      } catch(e) {
        setError(e.message);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [sb, courseId]);

  /* ── Score engine — per student, per real activity ── */
  const MAX_TOTAL = 1200;

  function computeScore(student) {
    const act   = activityMap[student.id] || {};
    const dsMap = dayStatusMap[student.id] || {};
    const total = planDays?.length || 1;
    let score = 0;
    const bd = {};

    // 1. Days Completed (max 300)
    const completed   = Object.values(dsMap).filter(s => s === "Completed").length;
    const inProgress  = Object.values(dsMap).filter(s => s === "In Progress").length;
    const daysScore   = Math.min(300, Math.round((completed / Math.max(total,1)) * 280 + inProgress * 5));
    bd.days = { label:"Days Completed", icon:"📅", color:"#22c55e", pts:daysScore, max:300, raw:`${completed}/${total} days` };
    score += daysScore;

    // 2. Streak — consecutive completed day keys (max 100)
    const completedKeys = Object.entries(dsMap)
      .filter(([,v]) => v === "Completed").map(([k]) => k).sort();
    let maxStreak = 0, cur = 0;
    for (let i = 0; i < completedKeys.length; i++) {
      if (i === 0) { cur = 1; }
      else {
        const diff = (new Date(completedKeys[i]) - new Date(completedKeys[i-1])) / 86400000;
        cur = diff <= 2 ? cur + 1 : 1;
      }
      maxStreak = Math.max(maxStreak, cur);
    }
    const streakScore = Math.min(100, maxStreak * 8);
    bd.streak = { label:"Best Streak", icon:"🔥", color:"#f59e0b", pts:streakScore, max:100, raw:`${maxStreak} day streak` };
    score += streakScore;

    // 3. Quiz Performance (max 200)
    const quizScores = act.quizScores || {};
    const quizVals   = Object.values(quizScores);
    const avgQuiz    = quizVals.length > 0 ? quizVals.reduce((a,q) => a + (q.pct||0), 0) / quizVals.length : 0;
    const quizScore  = Math.min(200, Math.round((avgQuiz / 100) * 160 + quizVals.length * 8));
    bd.quiz = { label:"Quiz Performance", icon:"🎯", color:"#6366f1", pts:quizScore, max:200,
      raw: quizVals.length > 0 ? `${Math.round(avgQuiz)}% avg · ${quizVals.length} taken` : "None yet" };
    score += quizScore;

    // 4. Notebook Study (max 120)
    const nbViews    = Object.keys(act.notebookViews || {}).length;
    const codeRuns   = Object.values(act.codeRuns || {}).reduce((a,v) => a+v, 0);
    const nbScore    = Math.min(120, nbViews * 14 + Math.min(36, codeRuns * 3));
    bd.notebooks = { label:"Notebooks Studied", icon:"📓", color:"#8b5cf6", pts:nbScore, max:120, raw:`${nbViews} notebooks · ${codeRuns} code runs` };
    score += nbScore;

    // 5. Assignments Downloaded/Submitted (max 150)
    const assignCount = Object.keys(act.assignSubmits || {}).length;
    const assignScore = Math.min(150, assignCount * 25);
    bd.assignments = { label:"Assignments Submitted", icon:"📝", color:"#ec4899", pts:assignScore, max:150, raw:`${assignCount} submitted` };
    score += assignScore;

    // 6. Notes Written (max 80)
    const notesDays  = Object.keys(act.notesChars || {}).length;
    const notesTotal = Object.values(act.notesChars || {}).reduce((a,v) => a+v, 0);
    const notesScore = Math.min(80, notesDays * 10 + Math.min(30, Math.floor(notesTotal / 150)));
    bd.notes = { label:"Notes Written", icon:"🗒️", color:"#14b8a6", pts:notesScore, max:80, raw:`${notesDays} days · ${notesTotal} chars` };
    score += notesScore;

    // 7. Practicals Performed (max 100)
    const practicalCount = Object.values(act.practicals || {}).reduce((a,v) => a+v, 0);
    const practicalScore = Math.min(100, practicalCount * 12);
    bd.practicals = { label:"Practicals Done", icon:"⚗️", color:"#f97316", pts:practicalScore, max:100, raw:`${practicalCount} sessions` };
    score += practicalScore;

    // 8. Datasets Used (max 80)
    const dataCount = Object.keys(act.dataGenUses || {}).length;
    const dataScore = Math.min(80, dataCount * 20);
    bd.dataUsed = { label:"Datasets Used", icon:"🗃️", color:"#0ea5e9", pts:dataScore, max:80, raw:`${dataCount} datasets` };
    score += dataScore;

    // 9. Examples Explored (max 70)
    const exCount   = Object.keys(act.exampleViews || {}).length;
    const exScore   = Math.min(70, exCount * 10);
    bd.examples = { label:"Examples Explored", icon:"⚡", color:"#a855f7", pts:exScore, max:70, raw:`${exCount} days` };
    score += exScore;

    return { score: Math.min(MAX_TOTAL, Math.round(score)), breakdown:bd, streak:maxStreak, completed, inProgress };
  }

  /* ── Build ranked list ── */
  const ranked = students
    .filter(s => !filter.trim() || s.name.toLowerCase().includes(filter.toLowerCase()) || (s.email||"").toLowerCase().includes(filter.toLowerCase()))
    .map((s, i) => {
      const { score, breakdown, streak, completed, inProgress } = computeScore(s);
      return { ...s, score, breakdown, streak, completed, inProgress, totalDays: planDays?.length || 0 };
    })
    .sort((a, b) => {
      if (sortKey === "score")    return b.score    - a.score;
      if (sortKey === "streak")   return b.streak   - a.streak;
      if (sortKey === "progress") return b.completed - a.completed;
      return a.name.localeCompare(b.name);
    });

  const medals     = ["🥇","🥈","🥉"];
  const podiumBg   = [
    "linear-gradient(160deg,#fffbeb,#fef3c7)", 
    "linear-gradient(160deg,#f8fafc,#f1f5f9)",
    "linear-gradient(160deg,#fff7ed,#ffedd5)"
  ];
  const podiumBorder = ["#fcd34d","#cbd5e1","#fed7aa"];
  const podiumScore  = ["#d97706","#64748b","#b45309"];

  /* ── Tier labels ── */
  function getTier(score) {
    const pct = (score / MAX_TOTAL) * 100;
    if (pct >= 80) return { label:"🏆 Elite",      color:"#f59e0b", bg:"#fffbeb" };
    if (pct >= 60) return { label:"🥇 Advanced",   color:"#6366f1", bg:"#eef2ff" };
    if (pct >= 40) return { label:"⚡ Rising",     color:"#22c55e", bg:"#f0fdf4" };
    if (pct >= 20) return { label:"📚 Learning",   color:"#0ea5e9", bg:"#eff6ff" };
    return               { label:"🌱 Starter",     color:"#94a3b8", bg:"#f8fafc" };
  }

  /* ── Loading / error / empty ── */
  if (loading) return (
    <div style={{ display:"flex", alignItems:"center", justifyContent:"center", height:340, flexDirection:"column", gap:14 }}>
      <div style={{ width:44, height:44, border:"3px solid #e2e8f0", borderTopColor:"#6366f1", borderRadius:"50%", animation:"lms-spin .7s linear infinite" }}/>
      <p style={{ color:"#94a3b8", fontSize:14, fontWeight:600 }}>Fetching leaderboard…</p>
    </div>
  );

  if (error) return (
    <div style={{ textAlign:"center", padding:"48px 20px", color:"#ef4444" }}>
      <div style={{ fontSize:40, marginBottom:12 }}>⚠️</div>
      <p style={{ fontWeight:700, fontSize:15 }}>Failed to load leaderboard</p>
      <p style={{ fontSize:13, color:"#94a3b8", marginTop:6 }}>{error}</p>
    </div>
  );

  if (students.length === 0) return (
    <div style={{ textAlign:"center", padding:"64px 20px" }}>
      <div style={{ fontSize:52, marginBottom:16 }}>🏆</div>
      <h2 style={{ color:"#0f172a", fontSize:20, fontWeight:800, marginBottom:8 }}>No students enrolled yet</h2>
      <p style={{ color:"#94a3b8", fontSize:14, maxWidth:340, margin:"0 auto" }}>Once students join and start working, their real-time performance scores will appear here.</p>
    </div>
  );

  /* ── Inline styles (injected once) ── */
  const css = `
    .lb2-podium-card { border-radius:18px; padding:20px 14px; text-align:center; position:relative; transition:transform .18s; }
    .lb2-podium-card:hover { transform:translateY(-3px); }
    .lb2-row { display:flex; align-items:center; gap:12px; padding:14px 18px; border-radius:14px; border:1.5px solid #f1f5f9; background:#fff; transition:all .16s; margin-bottom:8px; }
    .lb2-row:hover { border-color:#e0e7ff; box-shadow:0 2px 14px rgba(99,102,241,.09); }
    .lb2-row.me { border-color:#6366f1 !important; background:linear-gradient(135deg,#eef2ff,#f5f3ff) !important; box-shadow:0 0 0 3px rgba(99,102,241,.13) !important; }
    .lb2-bar-track { flex:1; height:7px; background:#f1f5f9; border-radius:99px; overflow:hidden; min-width:60px; }
    .lb2-bar-fill  { height:100%; border-radius:99px; transition:width .7s cubic-bezier(.34,1.56,.64,1); }
    .lb2-chip { display:inline-flex; align-items:center; gap:4px; padding:3px 9px; border-radius:99px; font-size:11px; font-weight:700; }
    .lb2-sort { padding:6px 12px; border-radius:8px; border:1.5px solid #e2e8f0; background:#fff; color:#64748b; font-size:12px; font-weight:700; cursor:pointer; transition:all .14s; font-family:inherit; white-space:nowrap; }
    .lb2-sort.on { background:#0f172a; color:#fff; border-color:#0f172a; }
    .lb2-detail { background:#f8fafc; border-radius:12px; padding:16px; margin-top:10px; display:grid; grid-template-columns:repeat(auto-fill,minmax(170px,1fr)); gap:8px; }
    .lb2-metric-card { background:#fff; border:1px solid #e8edf3; border-radius:10px; padding:10px 12px; display:flex; align-items:center; gap:10px; }
    @keyframes lb2-in { 0%{opacity:0;transform:translateY(6px)} 100%{opacity:1;transform:translateY(0)} }
    .lb2-entry { animation:lb2-in .22s ease both; }
  `;

  const myRank = currentStudentId ? ranked.findIndex(s => s.id === currentStudentId) + 1 : null;

  return (
    <div style={{ width:"100%", animation:"lms-in .22s ease" }}>
      <style>{css}</style>

      {/* ── Header ── */}
      <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:20 }}>
        <div style={{ width:46, height:46, background:"linear-gradient(135deg,#f59e0b,#f97316)", borderRadius:14, display:"flex", alignItems:"center", justifyContent:"center", fontSize:22, flexShrink:0, boxShadow:"0 4px 14px rgba(245,158,11,.3)" }}>🏆</div>
        <div style={{ flex:1 }}>
          <h1 style={{ fontSize:24, fontWeight:900, color:"#0f172a", margin:0, letterSpacing:"-.5px" }} className="lb2-title">Leaderboard</h1>
          <p style={{ fontSize:13, color:"#94a3b8", margin:0 }}>
            {studentMode
              ? myRank ? `You're ranked #${myRank} of ${ranked.length} students` : "Your performance vs peers"
              : `${ranked.length} student${ranked.length !== 1 ? "s" : ""} · real activity scores`}
          </p>
        </div>
        <div style={{ textAlign:"right", fontSize:11.5, color:"#94a3b8", lineHeight:1.6 }}>
          <div style={{ fontWeight:700, color:"#0f172a", fontSize:13 }} className="lb2-max-pts">{MAX_TOTAL.toLocaleString()} pts</div>
          <div>max possible</div>
        </div>
      </div>

      {/* ── Podium (top 3) ── */}
      {ranked.length >= 2 && (
        <div style={{ display:"flex", gap:10, marginBottom:24, alignItems:"flex-end", justifyContent:"center" }}>
          {/* 2nd */}
          {ranked[1] && (
            <div className="lb2-podium-card" style={{ flex:1, maxWidth:182, background:podiumBg[1], border:`1.5px solid ${podiumBorder[1]}` }}>
              <div style={{ fontSize:30, marginBottom:6 }}>🥈</div>
              <div style={{ width:48, height:48, borderRadius:"50%", background:"linear-gradient(135deg,#94a3b8,#475569)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:19, fontWeight:900, color:"#fff", margin:"0 auto 8px", boxShadow:"0 3px 10px rgba(148,163,184,.4)" }}>
                {ranked[1].name.charAt(0).toUpperCase()}
              </div>
              <div style={{ fontSize:13, fontWeight:800, color:"#0f172a", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }} className="lb2-podium-name">{ranked[1].name}</div>
              <div style={{ fontSize:18, fontWeight:900, color:podiumScore[1], marginTop:3 }}>{ranked[1].score.toLocaleString()}</div>
              <div style={{ fontSize:10, color:"#94a3b8", fontWeight:600 }} className="lb2-podium-pts">pts</div>
              <div style={{ marginTop:6 }}><span className="lb2-chip" style={{ background:getTier(ranked[1].score).bg, color:getTier(ranked[1].score).color }}>{getTier(ranked[1].score).label}</span></div>
              {currentStudentId === ranked[1].id && <div style={{ position:"absolute", top:8, right:8, background:"#6366f1", color:"#fff", fontSize:9, fontWeight:800, padding:"2px 7px", borderRadius:99 }}>YOU</div>}
            </div>
          )}
          {/* 1st */}
          {ranked[0] && (
            <div className="lb2-podium-card" style={{ flex:1, maxWidth:210, background:podiumBg[0], border:`2px solid ${podiumBorder[0]}`, paddingTop:26, paddingBottom:26, boxShadow:"0 8px 32px rgba(245,158,11,.18)" }}>
              <div style={{ fontSize:36, marginBottom:6 }}>🥇</div>
              <div style={{ width:58, height:58, borderRadius:"50%", background:"linear-gradient(135deg,#f59e0b,#d97706)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:24, fontWeight:900, color:"#fff", margin:"0 auto 10px", boxShadow:"0 6px 20px rgba(245,158,11,.45)" }}>
                {ranked[0].name.charAt(0).toUpperCase()}
              </div>
              <div style={{ fontSize:15, fontWeight:900, color:"#0f172a", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }} className="lb2-podium-name">{ranked[0].name}</div>
              <div style={{ fontSize:24, fontWeight:900, color:podiumScore[0], marginTop:4 }}>{ranked[0].score.toLocaleString()}</div>
              <div style={{ fontSize:11, color:"#92400e", fontWeight:700 }} className="lb2-podium-pts">pts</div>
              <div style={{ marginTop:8 }}><span className="lb2-chip" style={{ background:getTier(ranked[0].score).bg, color:getTier(ranked[0].score).color }}>{getTier(ranked[0].score).label}</span></div>
              {currentStudentId === ranked[0].id && <div style={{ position:"absolute", top:10, right:10, background:"#6366f1", color:"#fff", fontSize:9, fontWeight:800, padding:"2px 7px", borderRadius:99 }}>YOU</div>}
            </div>
          )}
          {/* 3rd */}
          {ranked[2] && (
            <div className="lb2-podium-card" style={{ flex:1, maxWidth:182, background:podiumBg[2], border:`1.5px solid ${podiumBorder[2]}` }}>
              <div style={{ fontSize:30, marginBottom:6 }}>🥉</div>
              <div style={{ width:48, height:48, borderRadius:"50%", background:"linear-gradient(135deg,#f97316,#ea580c)", display:"flex", alignItems:"center", justifyContent:"center", fontSize:19, fontWeight:900, color:"#fff", margin:"0 auto 8px", boxShadow:"0 3px 10px rgba(249,115,22,.4)" }}>
                {ranked[2].name.charAt(0).toUpperCase()}
              </div>
              <div style={{ fontSize:13, fontWeight:800, color:"#0f172a", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }} className="lb2-podium-name">{ranked[2].name}</div>
              <div style={{ fontSize:18, fontWeight:900, color:podiumScore[2], marginTop:3 }}>{ranked[2].score.toLocaleString()}</div>
              <div style={{ fontSize:10, color:"#92400e", fontWeight:600 }} className="lb2-podium-pts">pts</div>
              <div style={{ marginTop:6 }}><span className="lb2-chip" style={{ background:getTier(ranked[2].score).bg, color:getTier(ranked[2].score).color }}>{getTier(ranked[2].score).label}</span></div>
              {currentStudentId === ranked[2].id && <div style={{ position:"absolute", top:8, right:8, background:"#6366f1", color:"#fff", fontSize:9, fontWeight:800, padding:"2px 7px", borderRadius:99 }}>YOU</div>}
            </div>
          )}
        </div>
      )}

      {/* ── Controls ── */}
      <div style={{ display:"flex", gap:8, marginBottom:16, flexWrap:"wrap", alignItems:"center" }}>
        <div style={{ display:"flex", gap:4, flexWrap:"wrap" }}>
          {[["score","⭐ Score"],["streak","🔥 Streak"],["progress","📅 Days"],["name","🔤 Name"]].map(([k,label]) => (
            <button key={k} className={`lb2-sort${sortKey===k?" on":""}`} onClick={() => setSortKey(k)}>{label}</button>
          ))}
        </div>
        <input className="lms-input" value={filter} onChange={e=>setFilter(e.target.value)}
          placeholder="🔍 Search student…"
          style={{ flex:1, minWidth:140, fontSize:12.5, padding:"7px 12px" }} />
      </div>

      {/* ── Ranked list ── */}
      <div>
        {ranked.map((s, i) => {
          const isMe     = currentStudentId === s.id;
          const tier     = getTier(s.score);
          const barPct   = Math.round((s.score / MAX_TOTAL) * 100);
          const barColor = i===0 ? "#f59e0b" : i===1 ? "#94a3b8" : i===2 ? "#cd7f32" : isMe ? "#6366f1" : "#3b82f6";
          const isOpen   = expanded === s.id;
          const bd       = s.breakdown;

          return (
            <div key={s.id} className={`lb2-entry lb2-row${isMe?" me":""}`}
              style={{ flexDirection:"column", alignItems:"stretch", cursor:"pointer", animationDelay:`${i * 0.035}s` }}
              onClick={() => setExpanded(p => p === s.id ? null : s.id)}>

              {/* Main row */}
              <div style={{ display:"flex", alignItems:"center", gap:12 }}>
                {/* Rank */}
                <div style={{ width:36, height:36, borderRadius:10, background:i<3?"transparent":"#f8fafc", border:i<3?"none":"1.5px solid #e2e8f0", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0, fontSize:i<3?22:13, fontWeight:800, color:"#94a3b8" }} className="lb2-rank-badge">
                  {i<3 ? medals[i] : `#${i+1}`}
                </div>

                {/* Avatar */}
                <div style={{ width:40, height:40, borderRadius:"50%", background:`linear-gradient(135deg,${isMe?"#6366f1,#8b5cf6":"#3b82f6,#60a5fa"})`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, fontWeight:900, color:"#fff", flexShrink:0, boxShadow:`0 2px 8px ${isMe?"rgba(99,102,241,.3)":"rgba(59,130,246,.25)"}` }}>
                  {s.name.charAt(0).toUpperCase()}
                </div>

                {/* Name + bar */}
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:7, marginBottom:5, flexWrap:"wrap" }}>
                    <span style={{ fontSize:14, fontWeight:800, color:"#0f172a", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }} className="lb2-name">{s.name}</span>
                    {isMe && <span className="lb2-chip" style={{ background:"#eef2ff", color:"#6366f1" }}>YOU</span>}
                    <span className="lb2-chip" style={{ background:tier.bg, color:tier.color }}>{tier.label}</span>
                    {s.streak > 0 && <span className="lb2-chip" style={{ background:"#fff7ed", color:"#f59e0b" }}>🔥 {s.streak}d</span>}
                  </div>
                  <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                    <div className="lb2-bar-track">
                      <div className="lb2-bar-fill" style={{ width:`${barPct}%`, background:`linear-gradient(90deg,${barColor},${barColor}99)` }}/>
                    </div>
                    <span style={{ fontSize:11, color:"#94a3b8", fontWeight:700, flexShrink:0 }}>{barPct}%</span>
                  </div>
                </div>

                {/* Score + progress chips */}
                <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:4, flexShrink:0 }}>
                  <span style={{ fontSize:18, fontWeight:900, color:i===0?"#f59e0b":i===1?"#64748b":i===2?"#b45309":isMe?"#6366f1":"#0f172a", letterSpacing:"-.5px" }} className="lb2-score">
                    {s.score.toLocaleString()}
                  </span>
                  <span style={{ fontSize:10, color:"#94a3b8", fontWeight:600 }}>pts</span>
                  <span style={{ fontSize:10.5, color:"#22c55e", fontWeight:700 }}>{s.completed}/{s.totalDays} days</span>
                </div>

                {/* Expand arrow */}
                <div style={{ fontSize:12, color:"#94a3b8", flexShrink:0, transform:isOpen?"rotate(180deg)":"none", transition:"transform .2s" }}>▼</div>
              </div>

              {/* ── Expanded breakdown ── */}
              {isOpen && (
                <div className="lb2-detail" onClick={e => e.stopPropagation()}>
                  {Object.values(bd).map(m => (
                    <div key={m.label} className="lb2-metric-card">
                      <div style={{ width:32, height:32, borderRadius:8, background:m.color+"18", display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, flexShrink:0 }}>{m.icon}</div>
                      <div style={{ minWidth:0 }}>
                        <div style={{ fontSize:11, fontWeight:800, color:"#0f172a", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }} className="lb2-metric-label">{m.label}</div>
                        <div style={{ display:"flex", alignItems:"baseline", gap:4, marginTop:1 }}>
                          <span style={{ fontSize:15, fontWeight:900, color:m.color }}>{m.pts}</span>
                          <span style={{ fontSize:10, color:"#94a3b8", fontWeight:600 }}>/ {m.max}</span>
                        </div>
                        <div style={{ fontSize:10.5, color:"#64748b", marginTop:1, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{m.raw}</div>
                        <div style={{ height:3, background:"linear-gradient(145deg,#E4E9F2,#EDF1F7)", boxShadow:"inset 1px 1px 3px #C4CDD9", borderRadius:99, marginTop:4, overflow:"hidden" }}>
                          <div style={{ height:"100%", borderRadius:99, background:m.color, width:`${Math.round((m.pts/m.max)*100)}%`, transition:"width .5s" }}/>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* ── Scoring guide ── */}
      <div style={{ marginTop:28, padding:"20px 22px", background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", borderRadius:20, border:"1px solid #fff", boxShadow:"12px 12px 28px #C4CDD9,-8px -8px 20px #fff" }} className="lb2-guide-wrap">
        <p style={{ fontSize:11, fontWeight:800, color:"#94a3b8", textTransform:"uppercase", letterSpacing:".08em", marginBottom:12 }} className="lb2-guide-title">Score Breakdown (max {MAX_TOTAL.toLocaleString()} pts)</p>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(190px,1fr))", gap:8 }}>
          {[
            { icon:"📅", label:"Days Completed",      max:300, note:"280 × completion rate + in-progress bonus" },
            { icon:"🔥", label:"Best Streak",          max:100, note:"8 pts/consecutive day (weekends forgiven)" },
            { icon:"🎯", label:"Quiz Performance",     max:200, note:"Avg score + 8 pts per quiz taken" },
            { icon:"📓", label:"Notebooks Studied",    max:120, note:"14 pts/notebook + 3 pts/code run" },
            { icon:"📝", label:"Assignments Submitted",max:150, note:"25 pts per downloaded assignment" },
            { icon:"🗒️", label:"Notes Written",        max:80,  note:"10 pts/day + length bonus" },
            { icon:"⚗️", label:"Practicals Done",      max:100, note:"12 pts per code run or dataset use" },
            { icon:"🗃️", label:"Datasets Used",        max:80,  note:"20 pts per Data Generator dataset" },
            { icon:"⚡", label:"Examples Explored",    max:70,  note:"10 pts per day's examples viewed" },
          ].map(m => (
            <div key={m.label} style={{ display:"flex", gap:10, alignItems:"flex-start", padding:"12px 14px", background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", borderRadius:14, border:"1px solid #fff", boxShadow:"6px 6px 14px #C4CDD9,-4px -4px 10px #fff" }} className="lb2-guide-card">
              <span style={{ fontSize:18, flexShrink:0 }}>{m.icon}</span>
              <div>
                <div style={{ display:"flex", gap:6, alignItems:"baseline", flexWrap:"wrap" }}>
                  <span style={{ fontSize:12, fontWeight:700, color:"#0f172a" }} className="lb2-guide-label">{m.label}</span>
                  <span style={{ fontSize:10, color:"#94a3b8", fontWeight:700 }}>max {m.max}</span>
                </div>
                <div style={{ fontSize:11, color:"#64748b", lineHeight:1.45, marginTop:2 }} className="lb2-guide-note">{m.note}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}




/* ═══════════════════════════════════════════════════════════════════
   STUDENT DASHBOARD — personal progress overview for enrolled students
   Shows stats, activity breakdown, recent days, and a quick-actions strip.
═══════════════════════════════════════════════════════════════════ */
function StudentDashboard({ planDays, dayMap = {}, dayStatus, trainerDayStatus, studentActivity, dayData, startDate, courseId, onSelectDay, readOnly = false, enrolledCourses = [], pendingCourses = [], sb, studentId, groqKey, groqModel, notify }) {
  const act = studentActivity || {};
  const goToDay = readOnly ? null : onSelectDay;

  /* ── Build a reverse map: planDayIndex → dateKey (for status lookups) ── */
  // dayMap = { "YYYY-MM-DD": planDayIndex }  (built by buildDayMap)
  // planDays items only have { dayNum, topic } — no .key — so we build it here
  const indexToKey = {};   // { planDayIndex: "YYYY-MM-DD" }
  for (const [dateKey, idx] of Object.entries(dayMap)) {
    indexToKey[idx] = dateKey;
  }

  // Enrich planDays with their resolved date key
  const enrichedDays = planDays.map((d, i) => ({ ...d, key: indexToKey[i] || null }));

  /* ── Derived stats ── */
  const totalDays   = planDays.length;
  const completed   = enrichedDays.filter(d => d.key && dayStatus[d.key] === "Completed").length;
  const inProgress  = enrichedDays.filter(d => d.key && dayStatus[d.key] === "In Progress").length;
  const pct         = totalDays ? Math.round((completed / totalDays) * 100) : 0;

  const codeRuns    = Object.values(act.codeRuns    || {}).reduce((a, v) => a + v, 0);
  const practicals  = Object.values(act.practicals  || {}).reduce((a, v) => a + v, 0);
  const exViews     = Object.keys(act.exampleViews  || {}).length;
  const resViews    = Object.keys(act.resourceViews || {}).length;
  const assigns     = Object.keys(act.assignSubmits || {}).length;
  const dataGens    = Object.keys(act.dataGenUses   || {}).length;

  // Quiz stats — sourced from lms_student_activity.quizScores (persisted immediately on submit)
  const quizVals    = Object.values(act.quizScores || {});
  const quizTaken   = quizVals.length;
  const avgQuizPct  = quizTaken > 0
    ? Math.round(quizVals.reduce((a, q) => a + (q.pct || 0), 0) / quizTaken)
    : null;

  const joinedAt    = act.joinedAt ? new Date(act.joinedAt).toLocaleDateString() : "—";
  const lastSeen    = act.lastSeen ? new Date(act.lastSeen).toLocaleString()     : "—";

  /* ── Recent 5 days with any activity ── */
  const recentDays = enrichedDays
    .filter(d => d.key && dayStatus[d.key] && dayStatus[d.key] !== "Not Started")
    .slice(-5)
    .reverse();

  /* ── Next up: first non-Completed day ── */
  const nextDay = enrichedDays.find(d => !d.key || !dayStatus[d.key] || dayStatus[d.key] === "Not Started");

  /* ── Trainer unlock status ── */
  const unlockedByTrainer = enrichedDays.filter(d => d.key && trainerDayStatus[d.key] && trainerDayStatus[d.key] !== "Not Started").length;

  /* ── Tiny helpers ── */
  const card = (style) => ({
    background: "#fff",
    borderRadius: 14,
    padding: "18px 20px",
    boxShadow: "0 1px 6px rgba(0,0,0,.07)",
    border: "1px solid #f1f5f9",
    ...style,
  });

  const statBox = (icon, value, label, color) => (
    <div style={{ ...card(), display:"flex", alignItems:"center", gap:12, minWidth:0 }}>
      <div style={{ width:42, height:42, borderRadius:12, background:`${color}18`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:20, flexShrink:0 }}>{icon}</div>
      <div style={{ minWidth:0, flex:1 }}>
        <div style={{ fontSize:22, fontWeight:800, color:"#0f172a", lineHeight:1 }}>{value}</div>
        <div style={{ fontSize:11.5, color:"#64748b", marginTop:3, whiteSpace:"normal", lineHeight:1.3 }}>{label}</div>
      </div>
    </div>
  );

  const statusColor = { "Completed":"#22c55e", "In Progress":"#f59e0b", "Not Started":"#e2e8f0" };
  const statusDot   = (s) => <span style={{ display:"inline-block", width:8, height:8, borderRadius:"50%", background:statusColor[s]||"#e2e8f0", marginRight:6 }} />;

  return (
    <div style={{ width:"100%", display:"flex", flexDirection:"column", gap:20 }}>

      {/* ── Header ── */}
      <div style={{ ...card({ background:"linear-gradient(135deg,#3b82f6,#8b5cf6)", border:"none", color:"#fff" }) }}>
        <div style={{ fontSize:22, fontWeight:800, marginBottom:4 }}>📊 My Dashboard</div>
        <div style={{ fontSize:13, opacity:.85 }}>Joined {joinedAt} · Last active {lastSeen}</div>
        {courseId && <div style={{ fontSize:11, opacity:.6, marginTop:4 }}>Course ID: {courseId}</div>}
      </div>

      {/* ── Progress bar card ── */}
      <div style={card()}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
          <span style={{ fontWeight:700, fontSize:15, color:"#0f172a" }}>Overall Progress</span>
          <span style={{ fontWeight:800, fontSize:22, color:"#3b82f6" }}>{pct}%</span>
        </div>
        <div style={{ height:12, borderRadius:99, background:"#e2e8f0", overflow:"hidden" }}>
          <div style={{ height:"100%", width:`${pct}%`, background:"linear-gradient(90deg,#3b82f6,#8b5cf6)", borderRadius:99, transition:"width .4s" }} />
        </div>
        <div style={{ display:"flex", gap:20, marginTop:12, fontSize:12.5, color:"#64748b" }}>
          <span>✅ {completed} Completed</span>
          <span>🔄 {inProgress} In Progress</span>
          <span>📋 {totalDays - completed - inProgress} Not Started</span>
          <span style={{ marginLeft:"auto" }}>🔓 {unlockedByTrainer} unlocked by trainer</span>
        </div>
      </div>

      {/* ── Stat boxes grid ── */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))", gap:12 }}>
        {statBox("💻", codeRuns,   "Code Runs",         "#3b82f6")}
        {statBox("⚗️", practicals,  "Practicals",        "#f97316")}
        {statBox("📖", exViews,    "Examples Viewed",   "#8b5cf6")}
        {statBox("🔗", resViews,   "Resources Viewed",  "#06b6d4")}
        {statBox("📝", assigns,    "Assignments Done",  "#10b981")}
        {statBox("🤖", dataGens,   "Data Gen Uses",     "#f59e0b")}
        {statBox("🎯", avgQuizPct !== null ? `${avgQuizPct}%` : "—", `Quiz Avg (${quizTaken} taken)`, "#6366f1")}
      </div>

      {/* ── My Courses ── */}
      {(enrolledCourses.length > 0 || pendingCourses.length > 0) && (
        <div style={card()}>
          <div style={{ fontWeight:700, fontSize:14, color:"#0f172a", marginBottom:14 }}>📚 My Courses</div>
          {enrolledCourses.length > 0 && (
            <>
              <div style={{ fontSize:11, fontWeight:700, color:"#64748b", textTransform:"uppercase", letterSpacing:".07em", marginBottom:8 }}>✅ Enrolled</div>
              <div style={{ display:"flex", flexDirection:"column", gap:8, marginBottom: pendingCourses.length > 0 ? 16 : 0 }}>
                {enrolledCourses.map(e => {
                  const isActive = e.courseId === courseId;
                  return (
                    <div key={e.courseId} style={{ display:"flex", alignItems:"center", gap:12, padding:"10px 14px", borderRadius:10, background: isActive ? "#eff6ff" : "#f8fafc", border: `1.5px solid ${isActive ? "#bfdbfe" : "#e2e8f0"}` }}>
                      <div style={{ width:36, height:36, borderRadius:10, background: isActive ? "#3b82f6" : "#e2e8f0", display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, flexShrink:0 }}>📖</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontWeight:700, fontSize:13.5, color:"#0f172a", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{e.courseName || "Unnamed Course"}</div>
                        <div style={{ fontSize:11, color:"#64748b", marginTop:1 }}>Course ID: {e.courseId?.slice(0, 12)}…</div>
                      </div>
                      {isActive && <span style={{ fontSize:10, fontWeight:700, color:"#2563eb", background:"#dbeafe", padding:"2px 8px", borderRadius:99, flexShrink:0 }}>ACTIVE</span>}
                    </div>
                  );
                })}
              </div>
            </>
          )}
          {pendingCourses.length > 0 && (
            <>
              <div style={{ fontSize:11, fontWeight:700, color:"#64748b", textTransform:"uppercase", letterSpacing:".07em", marginBottom:8 }}>⏳ Pending Approval</div>
              <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                {pendingCourses.map(p => (
                  <div key={p.courseId} style={{ display:"flex", alignItems:"center", gap:12, padding:"10px 14px", borderRadius:10, background:"#fffbeb", border:"1.5px solid #fde68a" }}>
                    <div style={{ width:36, height:36, borderRadius:10, background:"#fef3c7", display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, flexShrink:0 }}>⏳</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontWeight:700, fontSize:13.5, color:"#92400e", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{p.courseName || "Unnamed Course"}</div>
                      <div style={{ fontSize:11, color:"#b45309", marginTop:1 }}>Requested {p.requestedAt ? new Date(p.requestedAt).toLocaleDateString() : "recently"} · Awaiting trainer approval</div>
                    </div>
                    <span style={{ fontSize:10, fontWeight:700, color:"#d97706", background:"#fef3c7", padding:"2px 8px", borderRadius:99, flexShrink:0 }}>PENDING</span>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      )}

      {/* ── Quiz breakdown (only if quizzes taken) ── */}
      {quizTaken > 0 && (
        <div style={card()}>
          <div style={{ fontWeight:700, fontSize:14, color:"#0f172a", marginBottom:12 }}>🎯 Quiz Scores (saved from lms_student_activity)</div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:8 }}>
            {Object.entries(act.quizScores || {}).map(([dayKey, qs]) => {
              const day = enrichedDays.find(d => d.key === dayKey);
              const pctColor = qs.pct >= 80 ? "#16a34a" : qs.pct >= 50 ? "#d97706" : "#dc2626";
              return (
                <div key={dayKey} style={{ padding:"10px 14px", borderRadius:14, background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", border:"1px solid #fff", boxShadow:"6px 6px 14px #C4CDD9,-4px -4px 10px #fff", fontSize:12.5 }}>
                  <div style={{ fontWeight:700, color:"#334155" }}>{day ? `Day ${day.dayNum}: ${day.topic}` : dayKey}</div>
                  <div style={{ fontWeight:800, color:pctColor, fontSize:16, marginTop:2 }}>{qs.pct}%</div>
                  <div style={{ fontSize:11, color:"#94a3b8" }}>{qs.score}/{qs.total} · {new Date(qs.date).toLocaleDateString()}</div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* ── Next up + Recent days side-by-side ── */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16 }}>

        {/* Next day to study */}
        <div style={card()}>
          <div style={{ fontWeight:700, fontSize:14, color:"#0f172a", marginBottom:12 }}>🚀 Up Next</div>
          {nextDay ? (
            <div
              onClick={() => goToDay?.(nextDay)}
              style={{ padding:"12px 14px", borderRadius:10, background:"#f0f9ff", border:"1.5px solid #bae6fd", cursor:goToDay?"pointer":"default", transition:"background .15s" }}
              onMouseEnter={e => e.currentTarget.style.background="#e0f2fe"}
              onMouseLeave={e => e.currentTarget.style.background="#f0f9ff"}
            >
              <div style={{ fontWeight:700, color:"#0369a1", fontSize:13 }}>Day {nextDay.dayNum}: {nextDay.topic}</div>
              {nextDay.subtopics?.length > 0 && (
                <div style={{ fontSize:11.5, color:"#64748b", marginTop:4 }}>{nextDay.subtopics.slice(0,2).join(" · ")}{nextDay.subtopics.length > 2 ? " …" : ""}</div>
              )}
              <div style={{ fontSize:11, color:"#94a3b8", marginTop:6 }}>Tap to open →</div>
            </div>
          ) : (
            <div style={{ fontSize:13, color:"#10b981", fontWeight:600 }}>🎉 All days completed!</div>
          )}
        </div>

        {/* Recent activity */}
        <div style={card()}>
          <div style={{ fontWeight:700, fontSize:14, color:"#0f172a", marginBottom:12 }}>🕒 Recent Days</div>
          {recentDays.length === 0 ? (
            <div style={{ fontSize:13, color:"#94a3b8" }}>No activity yet — open the Calendar to start!</div>
          ) : (
            <div style={{ display:"flex", flexDirection:"column", gap:7 }}>
              {recentDays.map(d => (
                <div
                  key={d.key}
                  onClick={() => goToDay?.(d)}
                  style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"10px 14px", borderRadius:14, background:"linear-gradient(145deg,#EDF1F7,#E4E9F2)", border:"1px solid #fff", boxShadow:"6px 6px 14px #C4CDD9,-4px -4px 10px #fff", cursor:goToDay?"pointer":"default", fontSize:12.5 }}
                  onMouseEnter={e => e.currentTarget.style.background="#f1f5f9"}
                  onMouseLeave={e => e.currentTarget.style.background="#f8fafc"}
                >
                  <span style={{ fontWeight:600, color:"#334155", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", maxWidth:150 }}>
                    {statusDot(d.key ? dayStatus[d.key] : undefined)}Day {d.dayNum}: {d.topic}
                  </span>
                  <span style={{ fontSize:11, color:statusColor[d.key ? dayStatus[d.key] : ""]||"#94a3b8", fontWeight:700, flexShrink:0, marginLeft:8 }}>
                    {(d.key && dayStatus[d.key]) || "Not Started"}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* ── Per-day breakdown table (top 10 with any status) ── */}
      {enrichedDays.filter(d => d.key && dayStatus[d.key]).length > 0 && (
        <div style={card()}>
          <div style={{ fontWeight:700, fontSize:14, color:"#0f172a", marginBottom:12 }}>📅 Day-by-Day Status</div>
          <div style={{ overflowX:"auto" }}>
            <table style={{ width:"100%", borderCollapse:"collapse", fontSize:12.5 }}>
              <thead>
                <tr style={{ background:"linear-gradient(145deg,#E4E9F2,#EDF1F7)" }}>
                  {["Day","Topic","My Status","Trainer Status","Quiz Score","Code Runs","Practicals"].map(h => (
                    <th key={h} style={{ padding:"8px 12px", textAlign:"left", fontWeight:700, color:"#475569", borderBottom:"1px solid #e2e8f0", whiteSpace:"nowrap" }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {enrichedDays.filter(d => d.key && dayStatus[d.key]).slice(0, 20).map((d, i) => (
                  <tr
                    key={d.key}
                    onClick={() => goToDay?.(d)}
                    style={{ background: i%2===0?"#fff":"#fafafa", cursor:goToDay?"pointer":"default" }}
                    onMouseEnter={e => e.currentTarget.style.background="#f0f9ff"}
                    onMouseLeave={e => e.currentTarget.style.background=i%2===0?"#fff":"#fafafa"}
                  >
                    <td style={{ padding:"8px 12px", color:"#64748b", fontWeight:600 }}>{d.dayNum}</td>
                    <td style={{ padding:"8px 12px", color:"#0f172a", maxWidth:200, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{d.topic}</td>
                    <td style={{ padding:"8px 12px" }}>
                      <span style={{ padding:"2px 10px", borderRadius:99, fontSize:11, fontWeight:700, background:`${statusColor[dayStatus[d.key]]||"#e2e8f0"}20`, color:statusColor[dayStatus[d.key]]||"#64748b" }}>
                        {dayStatus[d.key] || "—"}
                      </span>
                    </td>
                    <td style={{ padding:"8px 12px" }}>
                      <span style={{ padding:"2px 10px", borderRadius:99, fontSize:11, fontWeight:700, background:`${statusColor[trainerDayStatus[d.key]]||"#e2e8f0"}20`, color:statusColor[trainerDayStatus[d.key]]||"#94a3b8" }}>
                        {trainerDayStatus[d.key] || "—"}
                      </span>
                    </td>
                    <td style={{ padding:"8px 12px", fontWeight:700, textAlign:"center" }}>
                      {(act.quizScores||{})[d.key]
                        ? <span style={{ color:(act.quizScores[d.key].pct>=80?"#16a34a":act.quizScores[d.key].pct>=50?"#d97706":"#dc2626") }}>{act.quizScores[d.key].pct}%</span>
                        : <span style={{ color:"#cbd5e1" }}>—</span>}
                    </td>
                    <td style={{ padding:"8px 12px", color:"#3b82f6", fontWeight:600, textAlign:"center" }}>{(act.codeRuns||{})[d.key] || "—"}</td>
                    <td style={{ padding:"8px 12px", color:"#f97316", fontWeight:600, textAlign:"center" }}>{(act.practicals||{})[d.key] || "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ── AGENT 7: Adaptive Learning Path ── */}
      {groqKey && (
        <AdaptiveLearningPath
          sb={sb}
          studentId={studentId}
          courseId={courseId}
          planDays={planDays}
          dayMap={dayMap}
          studentActivity={studentActivity || {}}
          groqKey={groqKey}
          groqModel={groqModel}
          onSelectDay={onSelectDay}
          notify={notify || (() => {})}
          darkMode={false}
        />
      )}

    </div>
  );
}

