        <div key={i} style={{ fontFamily:"'Courier New',monospace", fontSize:12.5, lineHeight:1.9, color:l.k==="bl"?"transparent":(col[l.k]??C.textMid), minHeight:l.k==="bl"?6:undefined }}>{l.v??" "}</div>
